var e=JSON.parse(`[[3101,"Code splitting (розділення коду) — це техніка, яка дозволяє розбивати застосунок на кілька файлів (чанків). Це скорочує початковий час завантаження, оскільки на сторінку завантажуються лише необхідні частини.","Code splitting у Webpack використовують для оптимізації завантаження застосунку. Замість одного великого файлу створюється кілька чанків, які можуть завантажуватися в міру потреби. Webpack підтримує кілька способів розділення коду:\\nМножинні точки входу:\\nРозділення на рівні конфігурації:\\n\\nДинамічні імпорти:\\nЗавантаження модулів на запит:\\n\\nОптимізація спільних залежностей:\\nВикористання \`SplitChunksPlugin\` для виділення спільних модулів в окремий файл:\\n\\nCode splitting допомагає покращити швидкість завантаження та взаємодії із застосунком, особливо для великих проєктів.","entry: {\\n    main: './src/index.js',\\n    admin: './src/admin.js',\\n},\\noutput: {\\n    filename: '[name].bundle.js', // main.bundle.js і admin.bundle.js\\n},\\n\\nimport('./module.js').then((module) => {\\n    module.default();\\n});\\n\\noptimization: {\\n    splitChunks: {\\n        chunks: 'all',\\n    },\\n},"],[3102,"Tree shaking — це процес видалення невикористовуваного коду зі збирання. Він працює з модулями ES6, використовуючи статичний аналіз для виключення «мертвого» коду.","Tree shaking у Webpack видаляє з фінального коду частини, які не використовуються. Це особливо корисно для бібліотек, де імпортується лише частина функціональності.\\nПриклад:\\n\\nТут функція \`unused\` не використовується й буде видалена зі збирання, якщо ввімкнено режим \`production\` і використовується \`TerserPlugin\`.\\nTree shaking працює лише з модулями ES6 (import/export) і потребує оптимізації:\\n\\nЦе скорочує розмір коду й пришвидшує завантаження застосунку.","// utils.js\\nexport function used() {\\n    console.log('Used function');\\n}\\nexport function unused() {\\n    console.log('Unused function');\\n}\\n\\n// index.js\\nimport { used } from './utils';\\nused();\\n\\nmodule.exports = {\\n    mode: 'production', // Режим для ввімкнення tree shaking\\n    optimization: {\\n        usedExports: true, // Маркує використовувані експорти\\n    },\\n};"],[3103,"Webpack обробляє CSS за допомогою завантажувачів, таких як \`css-loader\` (для обробки \`@import\` і \`url()\`) і \`style-loader\` (для внесення CSS у DOM). У продакшені CSS може бути винесено в окремий файл.","Для роботи з CSS у Webpack використовують такі завантажувачі:\\n\\n- \`css-loader\`:\\nОбробляє CSS-файли й розв'язує імпорти (\`@import\` і \`url()\`).\\n\\n- \`style-loader\`:\\nВносить CSS у теги \`<style>\` всередині HTML.\\n\\n- \`MiniCssExtractPlugin\`:\\nВиносить CSS в окремий файл (рекомендується для продакшену).\\n\\nПриклад конфігурації:\\n\\nУ режимі розробки можна використовувати \`style-loader\` замість \`MiniCssExtractPlugin.loader\`. Це дозволяє швидше тестувати зміни стилів.","const MiniCssExtractPlugin = require('mini-css-extract-plugin');\\nmodule.exports = {\\n  module: {\\n    rules: [\\n      {\\n        test: /\\\\.css$/,\\n        use: [\\n          MiniCssExtractPlugin.loader, // Для продакшену\\n          'css-loader', // Обробка CSS\\n        ],\\n      },\\n    ],\\n  },\\n  plugins: [\\n    new MiniCssExtractPlugin({\\n     filename: '[name].css',\\n  }),\\n  ],\\n};"],[3104,"Звичайні вихідні карти (\`source-map\`) дають точне зіставлення між вихідним кодом і згенерованим, але вповільнюють збирання. Дешеві вихідні карти (\`cheap-source-map\`) працюють швидше, але менш точні, оскільки ігнорують інформацію про колонки та перетворення на рівні коду (наприклад, у Babel).","Вихідні карти допомагають зневаджувати згенерований код, відображаючи помилки в контексті вихідного коду. Webpack підтримує різні типи вихідних карт, які відрізняються точністю та швидкістю збирання:\\nЗвичайні вихідні карти (\`source-map\`):\\nДокладні карти, які включають інформацію про рядки та колонки. Вони зручні для точного зневадження, але значно вповільнюють процес збирання.\\nДешеві вихідні карти (\`cheap-source-map\`):\\nСкорочують час збирання, пропускаючи інформацію про колонки та трансформації (наприклад, Babel). Використовують для швидшого зневадження, але можуть бути менш точними.\\nПриклад налаштування:\\n\\nВибір типу вихідної карти залежить від того, що для вас важливіше: точність зневадження або швидкість збирання.","module.exports = {\\n    devtool: 'source-map', // Або 'cheap-source-map'\\n};"],[3105,"\`webpack-merge\` — це бібліотека, яка дозволяє об'єднувати кілька конфігурацій Webpack в одну. Її використовують для створення окремих конфігурацій для розробки, продакшену або інших цілей, щоб уникнути дублювання коду.","У проєктах часто потрібно розділяти конфігурацію Webpack на кілька частин, наприклад спільну (base), для розробки (development) і для продакшену (production). Бібліотека \`webpack-merge\` допомагає об'єднати ці конфігурації, зберігаючи код організованішим.\\nПриклад:\\n\\nЦе дозволяє гнучко налаштовувати збирання під різні сценарії, уникаючи повторення спільної конфігурації.","// webpack.common.js\\nmodule.exports = {\\n  entry: './src/index.js',\\n  output: {\\n    filename: 'bundle.js',\\n    path: __dirname + '/dist',\\n  },\\n};\\n// webpack.dev.js\\nconst { merge } = require('webpack-merge');\\nconst common = require('./webpack.common.js');\\nmodule.exports = merge(common, {\\n  mode: 'development',\\n  devtool: 'inline-source-map',\\n});\\n// webpack.prod.js\\nconst { merge } = require('webpack-merge');\\nconst common = require('./webpack.common.js');\\nmodule.exports = merge(common, {\\n  mode: 'production',\\n});"],[3106,"Webpack обробляє зображення через \`asset modules\` або завантажувачі, такі як \`file-loader\` і \`url-loader\`. Можна налаштувати автоматичне копіювання зображень у папку збирання або вбудувати їх як дані base64, якщо вони невеликі.","Для роботи із зображеннями Webpack пропонує кілька підходів:\\nAsset Modules (рекомендований спосіб):\\nДозволяє працювати із зображеннями без додаткових завантажувачів:\\n\\nВикористання \`file-loader\` (застаріло):\\nКопіює файли в директорію збирання й повертає посилання:\\n\\nОптимізація зображень:\\nДля стискання можна використовувати плагіни, наприклад \`image-minimizer-webpack-plugin\`:\\n\\nТакий підхід дозволяє покращити продуктивність застосунку, зменшуючи розмір ресурсів, що завантажуються.","module.exports = {\\n    module: {\\n        rules: [\\n          {\\n            test: /\\\\.(png|jpe?g|gif|svg)$/i,\\n            type: 'asset', // Автоматично вибирає між копіюванням файлу та вбудовуванням даних base64\\n          },\\n        ],\\n    },\\n};\\n\\nmodule.exports = {\\n    module: {\\n        rules: [\\n          {\\n            test: /\\\\.(png|jpe?g|gif)$/i,\\n            use: [\\n              {\\n                  loader: 'file-loader',\\n                  options: {\\n                      name: '[path][name].[ext]', // Налаштування імені файлу\\n                 },\\n              },\\n            ],\\n          },\\n        ],\\n    },\\n};\\n\\nconst ImageMinimizerPlugin = require('image-minimizer-webpack-plugin');\\nmodule.exports = {\\n    plugins: [\\n        new ImageMinimizerPlugin({\\n            minimizerOptions: {\\n              plugins: ['mozjpeg', 'pngquant'],\\n            },\\n        }),\\n    ],\\n};"],[3107,"Webpack може обробляти шрифти через \`asset modules\` або завантажувачі, такі як \`file-loader\`. Це дозволяє копіювати файли шрифтів у папку збирання або вбудовувати їх як base64, якщо вони невеликі.","Для роботи зі шрифтами у Webpack використовують \`asset/resource\` або додаткові завантажувачі, такі як \`file-loader\`.\\nПриклад конфігурації з використанням \`asset/resource\`:\\n\\nЯкщо використовується застарілий \`file-loader\`:\\n\\nТакий підхід забезпечує правильне підключення шрифтів, що важливо для стилізації та продуктивності застосунку.","module.exports = {\\n    module: {\\n        rules: [\\n          {\\n            test: /\\\\.(woff|woff2|eot|ttf|otf)$/i,\\n            type: 'asset/resource', // Копіює шрифти в папку збирання\\n          },\\n        ],\\n    },\\n};\\n\\nmodule.exports = {\\n    module: {\\n        rules: [\\n          {\\n            test: /\\\\.(woff|woff2|eot|ttf|otf)$/i,\\n            use: [\\n              {\\n                  loader: 'file-loader',\\n                  options: {\\n                      name: 'fonts/[name].[hash].[ext]', // Зберігає шрифти в окремій папці\\n                 },\\n              },\\n            ],\\n          },\\n        ],\\n    },\\n};"],[3108,"\`webpack-chunk-hash\` генерує унікальні хеші для чанків на основі їхнього вмісту. Це важливо для кешування: змінені файли отримують новий хеш, а незмінені залишаються закешованими, пришвидшуючи завантаження.","У Webpack хешування використовують для створення унікальних імен файлів, що допомагає браузеру визначити, чи потрібно оновити закешований ресурс. За замовчуванням використовується \`hash\`, який залежить від усього збирання. Проте це не завжди зручно, оскільки будь-які зміни призводять до зміни хешів усіх файлів.\\n\`webpack-chunk-hash\` генерує хеші на основі вмісту кожного окремого чанка. Наприклад:\\n\\nПереваги:\\n\\n- Зміна одного модуля не торкається хешів решти.\\n\\n- Ефективне використання кешу браузера.\\n\\nВ останніх версіях Webpack \`contenthash\` і \`chunkhash\` вбудовані й замінюють потребу в зовнішньому плагіні.","const WebpackChunkHash = require('webpack-chunk-hash');\\n\\nmodule.exports = {\\n    plugins: [\\n        new WebpackChunkHash(), // Унікальні хеші для чанків\\n    ],\\n};"],[3109,"\`html-webpack-plugin\` генерує HTML-файли для вашого застосунку. Він автоматично підключає скрипти та стилі, що створює Webpack, що спрощує налаштування й оновлення.","\`html-webpack-plugin\` — це плагін, який створює HTML-файли й автоматично підключає в них ресурси (JavaScript і CSS). Це особливо корисно, якщо імена файлів містять хеші або якщо у вас кілька точок входу.\\nПриклад налаштування:\\n\\nПереваги:\\n\\n- Автоматизація підключення ресурсів.\\n\\n- Підтримка кількох HTML-шаблонів.\\n\\n- Генерація HTML навіть без надання шаблону.\\n\\nЦе позбавляє потреби вручну оновлювати HTML під час зміни структури збирання.","const HtmlWebpackPlugin = require('html-webpack-plugin');\\n\\nmodule.exports = {\\n    plugins: [\\n        new HtmlWebpackPlugin({\\n            template: './src/index.html', // Шаблон HTML\\n            filename: 'index.html',      // Ім'я вихідного файлу\\n            inject: 'body',             // Скрипти підключаються в кінець body\\n        }),\\n    ],\\n};"],[3110,"HMR дозволяє оновлювати модулі в реальному часі, уникаючи повного перезавантаження сторінки. Webpack-dev-сервер відстежує зміни, перезбирає лише змінені частини й застосовує їх у браузері через WebSocket.","Hot Module Replacement (HMR) — це функція Webpack, яка покращує процес розробки. Замість перезавантаження всієї сторінки змінений код підвантажується в браузер, що зберігає поточний стан застосунку (наприклад, дані у формах).\\nHMR працює через WebSocket:\\n\\n- Відстеження змін: Webpack слідкує за змінами файлів за допомогою \`watch mode\`.\\n\\n- Збирання та повідомлення: Коли файл змінюється, Webpack перезбирає лише цей модуль і надсилає оновлення в браузер.\\n\\n- Застосування змін: Браузер застосовує зміни через HMR API без перезавантаження сторінки.\\n\\nНалаштування HMR:\\n\\nПриклад використання з React:\\n\\nHMR пришвидшує цикл розробки, особливо для SPA, але потребує підтримки в коді або відповідних завантажувачів (наприклад, \`style-loader\` для стилів).","module.exports = {\\n    devServer: {\\n        hot: true, // Увімкнює HMR\\n    },\\n};\\n\\nif (module.hot) {\\n    module.hot.accept('./App', () => {\\n        const NextApp = require('./App').default;\\n        ReactDOM.render(<NextApp />, document.getElementById('root'));\\n    });\\n}"],[3111,"Для збирання production Webpack використовує режим \`production\`, який включає оптимізації: мініфікацію, tree shaking і генерацію контент-хешів. Налаштування включає розділення коду, оптимізацію стилів і зображень.","У режимі \`production\` Webpack автоматично включає оптимізації, спрямовані на зменшення розміру та підвищення продуктивності:\\nМініфікація JavaScript: Використовується \`TerserPlugin\` для видалення невикористовуваного коду й скорочення синтаксису.\\nTree shaking: Видаляє мертвий код.\\nОптимізація CSS: За допомогою \`MiniCssExtractPlugin\` і мініфікаторів, таких як \`css-minimizer-webpack-plugin\`.\\nРозділення коду: Використання \`SplitChunksPlugin\` для виділення спільних модулів.\\nОптимізація зображень: Стискання графіки через плагіни.\\nПриклад конфігурації:\\n\\nЦе створює оптимальне збирання для продакшену з мінімальним розміром і максимальною швидкістю завантаження.","const MiniCssExtractPlugin = require('mini-css-extract-plugin');\\nconst CssMinimizerPlugin = require('css-minimizer-webpack-plugin');\\n\\nmodule.exports = {\\n    mode: 'production',\\n    output: {\\n        filename: '[name].[contenthash].js', // Контент-хеші для кешування\\n    },\\n    module: {\\n        rules: [\\n            {\\n              test: /\\\\.css$/,\\n              use: [MiniCssExtractPlugin.loader, 'css-loader'],\\n            },\\n        ],\\n    },\\n    optimization: {\\n        minimize: true,\\n        minimizer: [new CssMinimizerPlugin()],\\n        splitChunks: {\\n            chunks: 'all',\\n        },\\n    },\\n    plugins: [\\n        new MiniCssExtractPlugin({ filename: '[name].[contenthash].css' }),\\n    ],\\n};"],[3112,"До основних концепцій Webpack належать: точки входу, вихідні властивості, завантажувачі, плагіни, модулі, режими (\`development\`/\`production\`), розділення коду (code splitting), tree shaking і обробка залежностей.","Основні концепції Webpack:\\nТочка входу (\`entry\`): Визначає, з якого файлу починається збирання застосунку.\\n\\nВихідна властивість (\`output\`): Налаштовує, куди зберігається згенерований файл.\\n\\nЗавантажувачі (\`loaders\`): Перетворюють файли (CSS, зображення, TypeScript) у формат, який розуміє Webpack.\\n\\nПлагіни (\`plugins\`): Додають додаткові можливості (генерація HTML, оптимізація).\\n\\nМодулі: Webpack розглядає кожен файл як модуль і зв'язує їх у залежності.\\nРежим (\`mode\`):\\n\\n- \`development\`: Швидке збирання з вихідними картами.\\n\\n- \`production\`: Оптимізоване збирання з мініфікацією.\\n\\nCode Splitting: Ділить код на чанки для підвищення продуктивності.\\nTree Shaking: Видаляє невикористовуваний код.\\nDevServer: Інструмент для локальної розробки з HMR.\\nВисновок:\\nЦі концепції допомагають ефективно використовувати Webpack у розробці як невеликих, так і великих застосунків.","entry: './src/index.js',\\n\\noutput: {\\n    filename: 'bundle.js',\\n    path: __dirname + '/dist',\\n},\\n\\nrules: [\\n    { test: /\\\\.css$/, use: ['style-loader', 'css-loader'] },\\n],\\n\\nplugins: [new HtmlWebpackPlugin({ template: './src/index.html' })],"],[3113,"Для зменшення розміру пакета можна використовувати мініфікацію коду, tree shaking, lazy loading, розділення коду (code splitting), оптимізацію зображень і виключення непотрібних залежностей.","Основні стратегії для зменшення розміру пакета:\\nTree Shaking: Видаляє невикористовуваний код із модулів ES6.\\n\\nМініфікація: Мінімізує код, видаляючи пробіли, коментарі та скорочуючи ідентифікатори.\\nWebpack автоматично використовує \`TerserPlugin\` у режимі \`production\`.\\nРозділення коду (Code Splitting): Ділить код на чанки, щоб завантажувати лише необхідне.\\n\\nЗавантаження на вимогу (Lazy Loading): Підвантажує модулі лише за потреби.\\n\\nОптимізація зображень: Використовуйте плагіни для стискання, такі як \`image-minimizer-webpack-plugin\`.\\nЗаміна великих бібліотек: Знайдіть легші альтернативи для великих залежностей. Наприклад, замість \`moment.js\` використовуйте \`date-fns\`.\\nExclude/Include у завантажувачах: Обмежте області обробки файлів.\\n\\nВидалення мертвого коду: Переконайтеся, що непотрібні залежності виключено зі збирання.\\nЦі стратегії допоможуть зменшити розмір пакета, покращивши час завантаження та продуктивність застосунку.","optimization: {\\n    usedExports: true,\\n};\\n\\noptimization: {\\n    splitChunks: {\\n        chunks: 'all',\\n    },\\n};\\n\\nimport('./module').then(module => {\\n    module.default();\\n});\\n\\ntest: /\\\\.js$/,\\nexclude: /node_modules/,"],[3114,"Webpack можна налаштувати для різних середовищ, використовуючи окремі файли конфігурації або \`webpack-merge\`. У розробці важливі HMR і вихідні карти, а в продакшені — мініфікація та оптимізація ресурсів.","Для налаштування Webpack під різні середовища зручно використовувати три окремі файли конфігурації: \`webpack.common.js\`, \`webpack.dev.js\` і \`webpack.prod.js\`.\\nСпільна конфігурація (\`webpack.common.js\`):\\nМістить базові налаштування, спільні для всіх середовищ.\\n\\nКонфігурація для розробки (\`webpack.dev.js\`):\\nАкцент на швидкодію та зручність.\\n\\nКонфігурація для продакшену (\`webpack.prod.js\`):\\nФокус на оптимізації.\\n\\nЗа допомогою \`webpack-merge\` можна об'єднувати конфігурації залежно від середовища. Це гнучкий підхід, що дозволяє уникнути дублювання коду.","module.exports = {\\n  entry: './src/index.js',\\n  output: {\\n    filename: '[name].[contenthash].js',\\n    path: __dirname + '/dist',\\n  },\\n  module: {\\n    rules: [\\n      { test: /\\\\.css$/, use: ['style-loader', 'css-loader'] },\\n    ],\\n  },\\n};\\n\\nconst { merge } = require('webpack-merge');\\nconst common = require('./webpack.common.js');\\nmodule.exports = merge(common, {\\n  mode: 'development',\\n  devtool: 'inline-source-map',\\n  devServer: {\\n    hot: true,\\n  },\\n});\\n\\nconst { merge } = require('webpack-merge');\\nconst common = require('./webpack.common.js');\\nconst CssMinimizerPlugin = require('css-minimizer-webpack-plugin');\\nmodule.exports = merge(common, {\\n  mode: 'production',\\n  optimization: {\\n    minimize: true,\\n    minimizer: ['...', new CssMinimizerPlugin()],\\n  },\\n});"],[3115,"Для покращення продуктивності використовуйте кешування, розділення збирання на чанки, обмежте обробку через \`include/exclude\`, застосуйте \`thread-loader\` для паралельної обробки та оптимізуйте дерево залежностей.","Ключові способи оптимізації продуктивності Webpack:\\nКешування:\\nЗберігайте проміжні результати збирання для пришвидшення наступних.\\n\\nРозділення збирання:\\nДіліть код на чанки, щоб скоротити час збирання.\\n\\nОбмеження області обробки:\\nЗменште кількість файлів, що проходять через завантажувачі.\\n\\nПаралельна обробка:\\nВикористовуйте \`thread-loader\` для завантажувачів, щоб обробляти файли в кількох потоках.\\n\\nДинамічне імпортування: Завантажуйте модулі в міру потреби.\\nАналіз збирання: Використовуйте \`webpack-bundle-analyzer\` для вивчення структури збирання й видалення непотрібного коду.\\n\\nЦі методи допоможуть справитися з довгими збираннями та збільшенням розміру коду у великих застосунках.","module.exports = {\\n    cache: {\\n        type: 'filesystem', // Файлове кешування\\n    },\\n};\\n\\noptimization: {\\n    splitChunks: {\\n        chunks: 'all',\\n    },\\n};\\n\\ntest: /\\\\.js$/,\\ninclude: /src/,\\nexclude: /node_modules/,\\n\\nmodule.exports = {\\n   module: {\\n        rules: [\\n            {\\n              test: /\\\\.js$/,\\n              use: ['thread-loader', 'babel-loader'],\\n            },\\n        ],\\n    },\\n};\\n\\nconst { BundleAnalyzerPlugin } = require('webpack-bundle-analyzer');\\nmodule.exports = {\\n    plugins: [new BundleAnalyzerPlugin()],\\n};"],[3116,"Module Federation — це технологія, вбудована у Webpack 5, яка дозволяє кільком незалежним JavaScript-застосункам динамічно імпортувати код один в одного під час виконання. Це основа для архітектури Micro Frontends. Вона дозволяє розбити один великий застосунок (моноліт) на дрібніші, автономні частини, які можуть розроблятися, розгортатися й оновлюватися незалежно одна від одної, але при цьому працювати як єдине ціле в браузері користувача.","Module Federation кардинально змінює підхід до збирання та організації великих frontend-проєктів.\\nЯк це працює:\\n\\n- Є два типи застосунків: Host (хост, основний застосунок) і Remote (віддалений застосунок, мікросервіс).\\n\\n- Remote-застосунок компілюється й exposes (надає) деякі свої модулі (компоненти, хуки) для зовнішнього використання.\\n\\n- Host-застосунок компілюється з конфігурацією, яка вказує, звідки (з якої URL) і які модулі можна буде підвантажити.\\n\\n- Під час виконання (in browser) Host-застосунок динамічно завантажує необхідний код із Remote-застосунку й використовує його так, ніби це його власний модуль.\\n\\nПереваги:\\n\\n- Незалежність команд: Кожна команда може розробляти свою частину застосунку на своєму стеку (React, Vue, Angular) і зі своїм циклом випуску версій.\\n\\n- Незалежні деплої: Можна оновити одну частину застосунку (мікросервіс), не передеплоюючи все інше.\\n\\n- Розділення кодової бази: Застосунки більше не є монолітами, що спрощує їхнє розуміння та підтримку.\\n\\n- Спільні залежності: Технологія вміє ділитися спільними залежностями (наприклад, \`react\`, \`react-dom\`), щоб не завантажувати їх кілька разів.\\n\\nПриклад використання:\\nХост-застосунок (сайт-портал) динамічно підвантажує віджет кошика із зовсім іншого застосунку, який розробляє й деплоїть окрема команда.\\nВисновок:\\nModule Federation — це потужний інструмент для масштабування розробки та організації роботи кількох команд над одним великим продуктом, який дозволяє реалізувати архітектуру Micro Frontends.",null],[3117,"SVG і відео оптимізують різними способами, але мета одна — знизити вагу й навантаження на браузер. Для SVG використовують спрощення path, видалення зайвих даних і CSS-анімації. Відео оптимізують через кодеки, роздільність і стримінг. Часто SVG використовують для простих анімацій, а відео — для складних візуальних сцен. Вибір формату напряму впливає на продуктивність.","SVG і відео — два популярні, але принципово різні підходи до анімації, і оптимізують їх по-різному.\\nОптимізація SVG-анімацій\\nSVG добре підходить для іконок, ілюстрацій і простих анімацій.\\nОсновні прийоми:\\n\\n- Оптимізація структури SVG\\n\\n- видалення \`metadata\`, \`title\`, \`desc\`\\n\\n- об'єднання path\\n\\n- скорочення кількості точок\\n\\n- Анімації через CSS, а не SMIL або JS\\n\\n- \`transform\`\\n\\n- \`opacity\`\\n\\n- \`stroke-dashoffset\`\\n\\n- Мінімізація кількості анімованих елементів\\n\\n- анімація групи замість кожного path\\n\\n- відмова від складних фільтрів (\`filter\`, \`blur\`)\\n\\nОптимізація відео\\nВідео застосовують, коли анімація надто складна для SVG.\\nОсновні підходи:\\n\\n- Вибір правильного кодека\\n\\n- H.264 для сумісності\\n\\n- H.265 / VP9 для меншого розміру\\n\\n- Зниження роздільності та FPS\\n\\n- 30 FPS замість 60\\n\\n- мінімально достатня роздільність\\n\\n- Використання autoplay без звуку\\n\\n- дозволяє браузеру не блокувати завантаження\\n\\n- знижує енергоспоживання\\n\\n- Лениве завантаження\\n\\n- завантаження відео лише за потреби\\n\\n- використання poster-зображень\\n\\nВисновок\\nSVG підходить для легких, інтерактивних анімацій, відео — для складних сцен. Максимальна продуктивність досягається, коли формат вибрано усвідомлено й оптимізовано під конкретний сценарій.",".icon {\\n  transition: transform 0.3s ease;\\n}"],[3118,"Оптимізація асетів полягає у зменшенні їхнього розміру та завантаженні лише тоді, коли вони реально потрібні. Для зображень використовують стискання та сучасні формати, для відео — кодеки та зниження роздільності, для SVG — очищення та спрощення структури. Також важливі lazy loading і code splitting. Грамотна оптимізація асетів напряму покращує Core Web Vitals. Це базовий навик для production-фронтенду.","Асети часто складають основну частину ваги фронтенд-застосунку, тому їхня оптимізація критична для продуктивності.\\nОптимізація зображень\\nЗображення — найчастіше джерело зайвого трафіку.\\nОсновні підходи:\\n\\n- Використання сучасних форматів\\n\\n- \`WebP\`\\n\\n- \`AVIF\`\\nВони дають менший розмір за тієї самої якості.\\n\\n- Адаптивні зображення\\n\\n- різні розміри під різні екрани\\n\\n- завантаження мінімально потрібної роздільності\\n\\n- Стискання без втрати якості\\n\\n- видалення metadata\\n\\n- зниження якості до візуально непомітного рівня\\n\\nОптимізація відео\\nВідео особливо важкі, тому потребують окремої уваги:\\n\\n- Вибір кодека\\n\\n- H.264 для сумісності\\n\\n- VP9 / AV1 для меншого розміру\\n\\n- Зниження параметрів\\n\\n- роздільність\\n\\n- FPS\\n\\n- бітрейт\\n\\n- Відкладене завантаження\\n\\n- завантаження лише за потреби\\n\\n- використання \`poster\`\\n\\nОптимізація SVG\\nSVG часто виглядають легкими, але можуть бути перевантажені:\\n\\n- Очищення структури\\n\\n- видалення \`metadata\`\\n\\n- об'єднання path\\n\\n- Відмова від складних фільтрів\\n\\n- \`filter\`\\n\\n- \`mask\`\\n\\n- \`clipPath\`\\n\\n- Анімації через CSS\\n\\n- замість JavaScript\\n\\nЗагальні техніки\\n\\n- lazy loading асетів\\n\\n- code splitting\\n\\n- кешування через CDN\\n\\n- preloading лише критичних ресурсів\\n\\nВисновок\\nОптимізація асетів — це системна робота: правильний формат, мінімальний розмір і завантаження в потрібний момент. Без цього навіть добре написаний код не врятує продуктивність.","<img src=\\"image.webp\\" loading=\\"lazy\\" alt=\\"example\\" />"],[3119,"Збирач — це інструмент, який об'єднує вихідний код і ресурси проєкту в готові файли для браузера. Він уміє працювати з модулями, оптимізувати код і обробляти різні типи файлів. Найвідоміший збирач — Webpack, але також популярні Vite, Parcel і Rollup. Вибір збирача впливає на швидкість розробки та зручність підтримки проєкту.","Сучасний фронтенд рідко складається з одного файлу, тому без збирача обійтися практично неможливо.\\nВизначення\\nЗбирач (bundler) — це інструмент, який аналізує залежності проєкту й збирає їх в оптимізований набір файлів для використання в браузері.\\nОсновні завдання збирача\\n\\n- Об'єднання модулів\\n\\n- JavaScript, CSS та інші ресурси збираються в підсумкові файли\\n\\n- Трансформація коду\\n\\n- Підтримка сучасного синтаксису через транспіляцію\\n\\n- Оптимізація\\n\\n- Мініфікація\\n\\n- Видалення невикористовуваного коду\\n\\n- Робота з асетами\\n\\n- Зображення\\n\\n- Шрифти\\n\\n- CSS-файли\\n\\nПопулярні збирачі\\n\\n- Webpack\\n\\n- Гнучкий і розширюваний\\n\\n- Підходить для складних проєктів\\n\\n- Vite\\n\\n- Швидкий dev-сервер\\n\\n- Використовує нативні ES-модулі\\n\\n- Parcel\\n\\n- Мінімальне налаштування\\n\\n- Добрий для невеликих проєктів\\n\\n- Rollup\\n\\n- Часто використовують для бібліотек\\n\\n- Відмінна підтримка tree shaking\\n\\nВисновок\\nЗбирач — ключова частина фронтенд-інфраструктури, і розуміння його можливостей важливе для усвідомленого вибору інструментів та архітектури проєкту.",null],[3120,"Webpack заздалегідь збирає весь проєкт у бандли, навіть у режимі розробки. Vite у dev-режимі не збирає проєкт повністю, а використовує нативні ES-модулі браузера. За рахунок цього Vite запускається й оновлюється значно швидше. Під час production-збирання Vite також використовує повноцінний бандлінг.","Webpack і Vite вирішують одне завдання, але роблять це різними способами.\\nПідхід Webpack\\nWebpack працює за принципом попереднього збирання.\\n\\n- Аналізує всі залежності\\n\\n- Збирає їх у бандли\\n\\n- Віддає браузеру готовий результат\\n\\nЦе дає гнучкість, але вповільнює старт dev-сервера й hot-оновлення.\\nПідхід Vite\\nVite використовує можливості сучасних браузерів.\\n\\n- У dev-режимі код віддається як ES-модулі\\n\\n- Збирання відбувається лише для реально запрошених файлів\\n\\n- Оновлення виконуються майже миттєво\\n\\nДля production Vite усе ж виконує повноцінне збирання.\\nКлючові відмінності\\n\\n- Швидкість розробки\\n\\n- Vite швидший під час старту й оновлень\\n\\n- Конфігурація\\n\\n- Webpack потребує більше налаштувань\\n\\n- Vite простіший з коробки\\n\\n- Зрілість екосистеми\\n\\n- Webpack має величезну кількість плагінів\\n\\n- Vite активно розвивається, але екосистема молодша\\n\\nВисновок\\nWebpack підходить для складних і нестандартних кейсів, а Vite — для швидкої та зручної розробки сучасних застосунків.",null],[3121,"У режимі розробки збирач відповідає за швидкі оновлення та зручне зневадження. У production-режимі він зосереджується на оптимізації та продуктивності. Це два різні сценарії з різними вимогами. Правильне налаштування збирача дозволяє отримати баланс між швидкістю розробки та якістю продукту.","Збирач відіграє різну роль на різних етапах життєвого циклу застосунку.\\nВплив на розробку\\nПід час розробки важлива швидкість і зручність.\\n\\n- Dev-сервер\\n\\n- Швидкий запуск проєкту\\n\\n- Автоматичне перезавантаження сторінки\\n\\n- Hot Module Replacement\\n\\n- Оновлення модулів без повного перезавантаження\\n\\n- Source maps\\n\\n- Спрощують зневадження коду\\n\\nВплив на production-збирання\\nУ production-середовищі пріоритети змінюються.\\n\\n- Мініфікація коду\\n\\n- Зменшення розміру файлів\\n\\n- Tree shaking\\n\\n- Видалення невикористовуваного коду\\n\\n- Code splitting\\n\\n- Завантаження лише потрібних частин застосунку\\n\\n- Оптимізація асетів\\n\\n- Стискання зображень і шрифтів\\n\\nЧому це важливо\\n\\n- Погане dev-налаштування вповільнює розробку\\n\\n- Погане production-налаштування погіршує продуктивність\\n\\nВисновок\\nЗбирач напряму впливає і на досвід розробника, і на швидкість роботи застосунку в користувачів, тому його налаштування — стратегічно важлива частина фронтенд-проєкту.",null],[3122,"Статику звичайно зберігають окремо від бізнес-логіки застосунку. До неї належать зображення, шрифти, іконки та скомпільовані файли CSS і JavaScript. У development їх може віддавати dev-сервер, а в production — CDN або вебсервер. Такий розподіл спрощує кешування й пришвидшує завантаження сторінки.","У фронтенд-проєктах статичні ресурси потребують особливого підходу через їхній обсяг і частоту використання.\\nЩо належить до статики\\nДо статичних ресурсів звичайно відносять:\\n\\n- Зображення\\n\\n- Шрифти\\n\\n- Іконки\\n\\n- Скомпільовані CSS і JS файли\\n\\nДе зберігається статика\\n\\n- Усередині проєкту\\n\\n- Папки \`public\` або \`assets\`\\n\\n- Використовують у development і на етапі збирання\\n\\n- Після збирання\\n\\n- Збирач кладе файли в директорію \`dist\` або \`build\`\\n\\n- Імена файлів часто містять hash для кешування\\n\\n- У зовнішньому сховищі\\n\\n- CDN\\n\\n- Об'єктні сховища\\n\\nЧому використовують CDN\\n\\n- Швидка доставка користувачам\\n\\n- Географічна близькість серверів\\n\\n- Ефективне кешування\\n\\nВисновок\\nГрамотна організація зберігання статики знижує навантаження на сервер і пришвидшує завантаження інтерфейсу для користувача.",null],[3123,"Динамічні імпорти та lazy loading дозволяють розбивати код на частини й завантажувати їх у міру потреби. Це зменшує розмір стартового бандла й пришвидшує перший рендер. Користувач завантажує лише той код, який реально потрібен у поточний момент. У результаті застосунок стає швидшим на старті.","Сучасні фронтенд-застосунки швидко зростають, і завантаження всього коду відразу стає неефективним.\\nПроблема великого бандла\\nЯкщо весь застосунок збирається в один бандл:\\n\\n- збільшується час завантаження\\n\\n- зростає час парсингу та виконання JS\\n\\n- погіршується First Contentful Paint\\n\\nНавіть якщо користувач не заходить на частину екранів, код для них усе одно завантажується.\\nЩо роблять динамічні імпорти\\nДинамічний імпорт (\`import()\`) повідомляє збирачу:\\n\\n- цей код можна винести в окремий чанк\\n\\n- завантажувати його лише за потреби\\n\\nWebpack або інший бандлер:\\n\\n- створює окремий файл\\n\\n- завантажує його асинхронно\\n\\nLazy loading у React\\nУ React частіше використовують зв'язку:\\n\\n- \`React.lazy\`\\n\\n- \`Suspense\`\\n\\nЦе дає:\\n\\n- зменшення initial bundle\\n\\n- завантаження сторінки лише під час переходу\\n\\n- контроль UX через fallback\\n\\nЯк це впливає на розмір бандла\\n\\n- Initial bundle\\n\\n- стає меншим\\n\\n- швидше завантажується й виконується\\n\\n- Загальний обсяг коду\\n\\n- не зменшується\\n\\n- просто розподіляється по чанках\\n\\n- Кешування\\n\\n- чанки кешуються окремо\\n\\n- зміни в одній частині не інвалідують увесь бандл\\n\\nОбмеження та підводні камені\\n\\n- надто дрібні чанки → багато мережевих запитів\\n\\n- lazy loading усередині критичного шляху → затримки UI\\n\\n- не все має сенс вантажити ліниво (наприклад, базову навігацію)\\n\\nКороткий висновок\\nДинамічні імпорти та lazy loading зменшують розмір стартового бандла й пришвидшують перший рендер. Це один із ключових інструментів оптимізації продуктивності, але його потрібно застосовувати усвідомлено, не дробячи код без потреби.","import('./HeavyModule').then(module => {\\n  module.run()\\n})\\n\\nconst SettingsPage = React.lazy(() => import('./SettingsPage'))"],[3124,"Time to Interactive — це час від початку завантаження сторінки до моменту, коли користувач може повноцінно з нею взаємодіяти. Сторінка вважається інтерактивною, коли обробники подій готові й основний потік не блокується. Ця метрика показує, наскільки швидко застосунок стає реально придатним до використання. Вона важливіша за просту швидкість завантаження. TTI напряму впливає на користувацький досвід.","Завантаження сторінки складається не лише з відображення контенту, а й із підготовки JavaScript-коду. Саме тут з'являється метрика Time to Interactive.\\nВизначення\\nTime to Interactive — це момент, коли:\\n\\n- основний контент відображено\\n\\n- JavaScript завантажено й виконано\\n\\n- інтерфейс реагує на користувацькі дії без затримок\\n\\nДля чого використовують TTI\\n\\n- Оцінка реального UX\\nКористувачеві важливо не побачити сторінку, а почати з нею працювати.\\n\\n- Пошук проблем продуктивності\\nДовгий TTI часто вказує на важкий JavaScript або великий бандл.\\n\\n- Порівняння оптимізацій\\nМетрика показує, чи покращили зміни реальну відгукливість застосунку.\\n\\nТипові причини поганого TTI\\n\\n- великий обсяг JS\\n\\n- блокуючі скрипти\\n\\n- відсутність code splitting\\n\\nВисновок\\nTime to Interactive відображає момент, коли застосунок стає справді usable. Оптимізація TTI — ключове завдання для продуктивних frontend-застосунків.",null],[3125,"Bundler напряму впливає на розмір і структуру JavaScript, який завантажується в браузер. Від його налаштувань залежить, скільки коду буде завантажено відразу і як швидко він виконається. Неправильна конфігурація призводить до великих бандлів і блокування main thread. Добре налаштований bundler пришвидшує завантаження й покращує метрики продуктивності. Це критично для складних застосунків.","Bundler визначає, у якому вигляді код потрапить у браузер, а отже напряму впливає на швидкість завантаження та інтерактивність застосунку.\\nОсновні способи впливу bundler на продуктивність\\n\\n- Розмір підсумкового бандла\\nBundler вирішує:\\n\\n- які модулі потраплять у фінальний файл\\n\\n- чи будуть видалені невикористовувані частини коду\\n\\nВеликий бандл довше завантажується й повільніше виконується.\\n\\n- Структура завантаження коду\\nBundler керує тим:\\n\\n- чи завантажується код одним файлом\\n\\n- чи розбитий він на чанки\\n\\nЦе напряму впливає на \`Time to Interactive\`.\\n\\n- Оптимізація JavaScript\\nУ процесі збирання може виконуватися:\\n\\n- мініфікація\\n\\n- видалення коментарів\\n\\n- спрощення виразів\\n\\n- Порядок виконання\\nНеправильне збирання може призвести до того, що важкий код виконається надто рано й заблокує інтерфейс.\\n\\nПриклад впливу\\n\\nВисновок\\nBundler — це не просто інструмент збирання, а ключовий фактор продуктивності frontend-застосунку. Його конфігурація напряму впливає на швидкість завантаження та відгукливість інтерфейсу.","// без розділення коду\\nimport './heavyFeature'\\n\\n// з лінивим завантаженням\\nimport('./heavyFeature')"],[3126,"Розмір бандла зменшують за рахунок видалення невикористовуваного коду й розділення завантаження. Використовують code splitting, tree shaking і ліниве завантаження. Також важливо контролювати залежності та уникати важких бібліотек. Мініфікація та компресія доповнюють ці підходи. У сукупності вони істотно пришвидшують завантаження.","Оптимізація розміру бандла — одне з ключових завдань під час розробки продуктивних frontend-застосунків.\\nОсновні підходи\\n\\n- Tree shaking\\nДозволяє видалити невикористовувані експортовані частини модулів.\\nПрацює ефективно за використання ES-модулів.\\n\\n- Code splitting\\nКод розбивається на незалежні чанки, які завантажуються в міру потреби.\\nЦе знижує обсяг початкового завантаження.\\n\\n- Lazy loading\\nВажкі частини застосунку завантажуються лише під час фактичного використання.\\n\\n- Контроль залежностей\\n\\n- заміна великих бібліотек на легші аналоги\\n\\n- імпорт лише потрібних модулів\\n\\n- Мініфікація та стискання\\n\\n- видалення пробілів та імен змінних\\n\\n- gzip або brotli на сервері\\n\\nПобічні ефекти\\n\\n- надто агресивний splitting може збільшити кількість запитів\\n\\n- складніше зневаджувати код\\n\\nВисновок\\nЗменшення бандла досягається не одним прийомом, а комбінацією стратегій. Головна мета — мінімізувати обсяг коду, який користувач завантажує й виконує під час старту застосунку.","const Feature = lazy(() => import('./Feature'))"],[3127,"Webpack налаштовує процес збирання frontend-застосунку. Через конфігурацію визначається, як обробляються файли та залежності. Можна керувати вхідними точками, вихідними файлами та завантажувачами. Також налаштовуються оптимізації та плагіни. Це робить збирання гнучким і розширюваним.","Webpack виступає центральним інструментом збирання frontend-коду.\\nОсновні області конфігурації\\nЧерез Webpack можна керувати такими аспектами:\\n\\n- entry — точки входу застосунку\\n\\n- output — формат і місце збирання\\n\\n- loaders — обробка JS, CSS, зображень\\n\\n- plugins — розширення логіки збирання\\n\\nРобота з ресурсами\\nWebpack дозволяє:\\n\\n- транспілювати JavaScript\\n\\n- обробляти стилі та препроцесори\\n\\n- підключати зображення та шрифти\\n\\n- оптимізувати розмір бандла\\n\\nОптимізація\\nЧасто налаштовують:\\n\\n- code splitting\\n\\n- lazy loading\\n\\n- tree shaking\\n\\n- мініфікацію\\n\\nОточення\\nДля різних середовищ звичайно використовують різні конфігурації:\\n\\n- development\\n\\n- production\\n\\n- test\\n\\nКороткий висновок\\nWebpack-конфігурація визначає весь процес збирання та оптимізації frontend-застосунку.",null],[3128,"Мініфікація — це зменшення розміру коду за рахунок видалення пробілів, коментарів і скорочення імен. Обфускація — це ускладнення коду для утруднення читання. Мініфікація спрямована на зменшення розміру, обфускація — на приховування логіки.","Мініфікація та обфускація — це різні етапи обробки коду перед публікацією.\\nМініфікація\\nВизначення:\\nМініфікація — це процес зменшення розміру файлу без зміни логіки програми.\\nЩо робиться:\\n\\n- видаляються пробіли\\n\\n- видаляються коментарі\\n\\n- скорочуються імена змінних\\n\\nПриклад:\\n\\nПісля мініфікації:\\n\\nОбфускація\\nВизначення:\\nОбфускація — це ускладнення структури коду для утруднення аналізу.\\nЩо може відбуватися:\\n\\n- перейменування змінних на безглузді\\n\\n- ускладнення логіки\\n\\n- кодогенерація\\n\\nРізниця\\n\\n- Мініфікація — про розмір\\n\\n- Обфускація — про читність\\n\\nДе використовують\\n\\n- Мініфікацію — майже завжди\\n\\n- Обфускацію — коли потрібно ускладнити аналіз коду\\n\\nВисновок\\nМініфікацію застосовують для пришвидшення завантаження, а обфускацію — для часткового захисту логіки застосунку.","function sum(a, b) { return a + b; }\\n\\nfunction a(b,c){return b+c}"],[3129,"Збирання проєкту включає налаштування збирача, транспіляції, обробки стилів і оптимізації. Звичайно використовують Webpack, Vite, Babel, PostCSS і TypeScript. Збирач об'єднує файли, оптимізує код і готує застосунок до запуску в браузері. Також налаштовують dev-сервер, source maps і розділення бандлів.","Налаштування збирання — це процес конфігурування інструментів, які перетворюють вихідний код в оптимізований production-бандл.\\nОсновні завдання збирання\\n\\n- Об'єднання файлів (bundling)\\n\\n- Транспіляція коду\\n\\n- Обробка CSS і зображень\\n\\n- Мініфікація\\n\\n- Розділення бандлів\\n\\nОсновні інструменти\\n\\n- Збирачі\\n\\n- Webpack\\n\\n- Vite\\n\\n- Parcel\\n\\n- Транспіляція\\n\\n- Babel\\n\\n- TypeScript\\n\\n- Робота зі стилями\\n\\n- PostCSS\\n\\n- Sass\\n\\nПриклад спрощеної конфігурації Webpack\\n\\nЩо налаштовують найчастіше\\n\\n- devServer\\n\\n- alias\\n\\n- code splitting\\n\\n- tree shaking\\n\\nВисновок\\nНалаштування збирання необхідне для оптимізації завантаження, сумісності з браузерами та зручності розробки.","module.exports = {\\n  entry: \\"./src/index.js\\",\\n  output: { filename: \\"bundle.js\\" }\\n};"],[3130,"Одна велика SPA — це єдиний застосунок, де весь код зібрано й розгорнуто разом. Монорепозиторій — це спосіб зберігання коду кількох проєктів в одному репозиторії, але вони можуть бути зібрані й розгорнуті як окремі застосунки або як один моноліт. Module Federation — це технологія Webpack, яка дозволяє динамічно завантажувати частини застосунку (модулі) з інших, незалежно зібраних і розгорнутих застосунків під час виконання, створюючи ефект єдиного застосунку з розподілених джерел.","У сучасній веброзробці існує кілька стратегій організації кодової бази та збирання застосунків, і кожна з них вирішує різні проблеми масштабування та командної роботи.\\n\\nОдна велика SPA (Моноліт)\\n\\nЦе класичний підхід: увесь застосунок — один проєкт, одне збирання, один деплой. Усі компоненти, сторінки та бібліотеки пов'язані на етапі збирання. Плюси: простота початкового налаштування, легкий рефакторинг у межах одного проєкту. Мінуси: у міру зростання кодова база стає громіздкою, збирання вповільнюються, оновлення потребують деплою всього застосунку, і командам складно працювати незалежно.\\n\\nМонорепозиторій (Monorepo)\\n\\nMonorepo — це практика зберігання коду кількох проєктів або пакетів в одному репозиторії Git. Це може бути як кілька незалежних SPA, так і набір бібліотек зі спільними залежностями. Інструменти на кшталт Lerna, Nx або Yarn Workspaces допомагають керувати залежностями та скриптами між пакетами. Ключова відмінність: збирання та деплой можуть бути як централізованими (усе збирається разом), так і ізольованими (кожен пакет — окреме збирання). Monorepo покращує спільну роботу над спільним кодом, але не вирішує проблему незалежного деплою та виконання.\\n\\nModule Federation\\n\\nЦе технологія, вбудована у Webpack 5, яка дозволяє одному JavaScript-застосунку динамічно завантажувати код з іншого застосунку під час виконання (runtime). По суті, це реалізація концепції Micro Frontends на рівні збирання. Застосунки (хости та віддалені модулі) збираються й розгортаються повністю незалежно. Хост-застосунок може завантажити, наприклад, компонент React або цілий маршрут з іншого домену. Це забезпечує справжню незалежність команд і можливість поетапного оновлення частин великого застосунку.\\n\\nПорівняння на практиці\\n\\n- Зв'язність: SPA — жорсткий зв'язок на етапі збирання. Monorepo — зв'язок на рівні коду та залежностей. Module Federation — слабкий зв'язок під час виконання.\\n\\n- Деплой: У SPA та монолітному Monorepo деплой усього застосунку. У Module Federation — незалежний деплой кожного мікрофронтенду.\\n\\n- Розмір бандла: SPA може мати величезний початковий бандл. Module Federation дозволяє завантажувати код на вимогу з різних джерел.\\n\\nПриклад конфігурації Module Federation\\n\\nВисновок: Module Federation варто застосовувати, коли потрібно побудувати великий застосунок, над різними частинами якого працюють незалежні команди, з можливістю окремого розгортання та оновлення компонентів. Monorepo краще підходить для централізованого керування багатьма пакетами або проєктами зі спільним кодом, але без вимог до незалежного runtime. Одна SPA залишається добрим вибором для невеликих або середніх проєктів, де складність розподіленої архітектури не виправдана.","// webpack.config.js віддаленого застосунку (remote)\\nconst ModuleFederationPlugin = require('webpack/lib/container/ModuleFederationPlugin');\\n\\nmodule.exports = {\\n  plugins: [\\n    new ModuleFederationPlugin({\\n      name: 'remote_app',\\n      filename: 'remoteEntry.js',\\n      exposes: {\\n        './Button': './src/components/Button', // Експортуємо компонент\\n      },\\n      shared: { react: { singleton: true } }, // Спільні залежності\\n    }),\\n  ],\\n};\\n\\n// webpack.config.js хоста (host)\\nnew ModuleFederationPlugin({\\n  name: 'host_app',\\n  remotes: {\\n    remote_app: 'remote_app@http://localhost:3001/remoteEntry.js',\\n  },\\n  shared: { react: { singleton: true } },\\n});\\n\\n// Код у хостовому застосунку для динамічного завантаження\\nconst RemoteButton = React.lazy(() => import('remote_app/Button'));"],[3131,"Shared-бібліотеки — це пакети зі спільним кодом (компоненти, утиліти, типи), які використовують кілька мікрофронтів. Правильно використовувати їх через централізоване керування версіями, наприклад у монорепозиторії за допомогою інструментів на кшталт Lerna або Nx. Це дозволяє синхронізувати оновлення й уникати конфліктів версій. Ключовий принцип — бібліотеки мають бути максимально незалежними та стабільними, щоб зміни в них не ламали мікрофронти.","Shared-бібліотеки (або спільні бібліотеки) в архітектурі мікрофронтів — це механізм для винесення повторюваного коду в окремі пакети, які потім можуть імпортувати незалежні команди, що розробляють різні частини застосунку. Це необхідно, щоб уникнути дублювання таких сутностей, як UI-компоненти (кнопки, модальні вікна), утиліти для форматування даних, клієнти API, константи або визначення TypeScript-типів.\\n\\nОсновні підходи до організації\\n\\nІснує кілька стратегій керування спільними бібліотеками:\\n\\n- Монорепозиторій (Monorepo): Усі мікрофронти та shared-бібліотеки перебувають в одному репозиторії. Інструменти на кшталт Nx, Lerna або Turborepo спрощують керування залежностями, скриптами збирання та версіонуванням усередині репозиторію. Зміни в бібліотеці відразу видні всім залежним проєктам, що спрощує синхронізацію, але потребує дисципліни, щоб не порушити зворотну сумісність.\\n\\n- Окремі npm-пакети: Бібліотеки публікують у приватний або публічний npm-реєстр. Кожен мікрофронт установлює їх як звичайні залежності, указуючи конкретну версію. Це дає більше ізоляції, але потребує ручного оновлення версій у кожному проєкті й може призвести до ситуації, коли різні мікрофронти використовують різні мажорні версії однієї бібліотеки.\\n\\n- Динамічне підключення (Module Federation): Технологія Webpack 5 Module Federation дозволяє завантажувати код спільних бібліотек динамічно під час виконання з одного джерела (host). Це зменшує розмір бандлів і гарантує, що всі мікрофронти використовують ту саму скомпільовану версію бібліотеки в рантаймі.\\n\\nПравила використання та найкращі практики\\n\\n- Мінімізація залежностей: Сама shared-бібліотека має мати якомога менше зовнішніх залежностей, особливо важких або конфліктних.\\n\\n- Семантичне версіонування (SemVer): Строге дотримання правил SemVer (MAJOR.MINOR.PATCH) для зворотної сумісності. Зміни, що ламають API, — лише в мажорних версіях.\\n\\n- Інверсія залежностей: Бібліотека не має залежати від бізнес-логіки конкретного мікрофронту. Вона надає абстракції та примітиви.\\n\\n- Тестування: Обов'язкове покриття бібліотеки unit- та інтеграційними тестами, оскільки її поломка торкнеться багатьох проєктів.\\n\\nПриклад структури в монорепозиторії\\n\\nВисновок: Shared-бібліотеки варто застосовувати для стабільного, добре протестованого коду, який справді використовується в кількох командах. Вони допомагають підтримувати однаковість інтерфейсу й скорочують витрати на розробку, але додають складність керування залежностями. Оптимальний підхід — монорепозиторій з інструментами автоматизації для середніх і великих проєктів, де важлива швидкість синхронізації змін.","// Структура проєкту з використанням Nx\\nmy-org/\\n├── apps/\\n│   ├── mf-auth/          # Мікрофронт \\"Авторизація\\"\\n│   └── mf-dashboard/     # Мікрофронт \\"Дашборд\\"\\n└── libs/\\n    └── shared-ui/        # Спільна UI-бібліотека\\n        ├── src/\\n        │   ├── Button.tsx\\n        │   └── index.ts  # Експорт компонентів\\n        ├── project.json  # Конфігурація Nx\\n        └── jest.config.js\\n\\n// Код компонента Button із shared-ui\\nimport React from 'react';\\n\\ntype ButtonProps = {\\n  label: string;\\n  onClick: () => void;\\n};\\n\\nexport const Button: React.FC<ButtonProps> = ({ label, onClick }) => {\\n  return (\\n    <button onClick={onClick}>\\n      {label}\\n    </button>\\n  );\\n};\\n\\n// Використання в мікрофронті mf-auth\\nimport { Button } from '@my-org/shared-ui';\\n\\nconst LoginForm = () => {\\n  return (\\n    <form>\\n      <Button\\n        label=\\"Увійти\\"\\n        onClick={() => console.log('Clicked')}\\n      />\\n    </form>\\n  );\\n};"],[3132,"Vite — це сучасний інструмент збирання, який використовує нативні ES-модулі в браузері для розробки, що забезпечує миттєвий запуск сервера та швидке гаряче перезавантаження модулів (HMR). Його переваги включають винятково швидку розробку завдяки відсутності попереднього збирання всього коду, вбудовану підтримку TypeScript, JSX, CSS та інших ресурсів, а також оптимізоване збирання для продакшену через Rollup. Обмеження Vite пов'язані з його архітектурою, орієнтованою на ES-модулі: можливі проблеми із застарілими браузерами в розробці, складності з деякими специфічними для Webpack плагінами та потреба адаптації для нестандартних робочих процесів.","Vite — це інструмент збирання та сервер розробки, створений Еваном Ю (автором Vue.js), який переосмислює підхід до фронтенд-розробки. Замість традиційного збирання всього коду в один бандл на етапі розробки Vite використовує нативні ES-модулі в браузері. Це дозволяє серверу розробки запускатися миттєво, оскільки він просто обслуговує вихідні файли, а браузер сам завантажує модулі в міру потреби.\\n\\nКлючові переваги Vite\\n\\n- Миттєвий запуск сервера: Не потрібно збирати весь застосунок, сервер запускається відразу, незалежно від розміру проєкту.\\n\\n- Швидкий Hot Module Replacement (HMR): Оновлення модулів відбуваються майже миттєво, без перезавантаження сторінки, що пришвидшує цикл розробки.\\n\\n- Оптимізоване збирання для продакшену: Для фінального збирання Vite використовує Rollup, що забезпечує ефективне дерево залежностей, розділення коду та інші оптимізації.\\n\\n- Вбудована підтримка сучасних технологій: TypeScript, JSX, CSS-модулі, PostCSS, WebAssembly та інші ресурси працюють з коробки без складного налаштування.\\n\\n- Плагінна система на основі Rollup: Дозволяє легко розширювати функціональність, використовуючи екосистему Rollup.\\n\\nПриклад налаштування простого проєкту\\n\\nОбмеження та компроміси\\n\\n- Вимоги до браузерів: У режимі розробки необхідна підтримка нативних ES-модулів, що виключає старі браузери (наприклад, IE11). Для продакшену код транспілюється.\\n\\n- Екосистема плагінів: Не всі плагіни Webpack доступні для Vite, що може потребувати пошуку альтернатив або написання власних адаптерів.\\n\\n- Складні конфігурації: Для нестандартних сценаріїв (наприклад, кастомні перетворення ресурсів) налаштування може бути менш гнучким порівняно з Webpack.\\n\\n- Залежність від Node.js: Як і більшість сучасних інструментів, потребує середовища Node.js.\\n\\nВисновок: Vite ідеально підходить для сучасних фронтенд-проєктів, де важлива швидкість розробки й використовується стек на основі ES-модулів. Його варто вибирати для нових застосунків на React, Vue, Svelte або інших фреймворках, де не потрібна підтримка застарілих браузерів у режимі розробки. Для проєктів із сильно кастомними процесами збирання або залежністю від специфічних плагінів Webpack може знадобитися додаткова оцінка.","// vite.config.js\\nimport { defineConfig } from 'vite';\\nimport react from '@vitejs/plugin-react';\\n\\nexport default defineConfig({\\n  plugins: [react()],\\n  server: {\\n    port: 3000,\\n    open: true\\n  },\\n  build: {\\n    outDir: 'dist',\\n    sourcemap: true\\n  }\\n});"],[3133,"Кастомне налаштування збирача, наприклад Webpack, часто призводить до проблем із продуктивністю збирання, складністю підтримки конфігурації та несумісністю плагінів. Розробники можуть зіткнутися з повільним збиранням через неоптимальні налаштування або дублювання коду. Також помилки в конфігурації можуть спричиняти проблеми з деревом залежностей (tree shaking) або завантаженням ресурсів. Підтримка такої конфігурації з часом ускладнюється, особливо під час оновлення версій збирача або його плагінів.","Кастомізація збирача модулів, такого як Webpack, дозволяє тонко налаштувати процес збирання під потреби проєкту, але несе низку ризиків і складностей. Основні проблеми виникають через складність конфігурації, потребу глибокого розуміння роботи збирача та постійного підтримання актуальності налаштувань під час оновлень екосистеми.\\nТипові проблеми\\n\\n- Складність підтримки й розуміння: Великі кастомні конфігурації стають «чорною скринькою» для нових членів команди. Відсутність документації посилює проблему.\\n- Продуктивність збирання: Неоптимальні налаштування (наприклад, некоректне кешування, надлишкові плагіни) можуть різко збільшити час збирання, особливо у великих проєктах.\\n- Крихкість і несумісність: Плагіни та лоадери можуть конфліктувати один з одним або переставати працювати після оновлення основної версії Webpack.\\n- Проблеми з деревом залежностей (Tree Shaking): Неправильне налаштування може перешкодити ефективному видаленню невикористовуваного коду, збільшуючи підсумковий бандл.\\n- Помилки в обробці ресурсів: Невірні налаштування для обробки CSS, зображень або шрифтів можуть призводити до помилок у рантаймі або до відсутності ресурсів у продакшені.\\nПриклад проблемної конфігурації\\nРозглянемо фрагмент конфігурації Webpack, де можуть ховатися проблеми:\\n\\nПрактичні рекомендації\\nЩоб мінімізувати ризики:\\n\\n- Починайте з готових конфігурацій (наприклад, \`create-react-app\`, \`@vue/cli\`) і витягуйте (eject) лише за крайньої потреби.\\n- Документуйте неочевидні частини конфігурації та причини вибору певних плагінів.\\n- Регулярно оновлюйте Webpack і плагіни, перевіряючи сумісність.\\n- Використовуйте інструменти для аналізу бандла (наприклад, \`webpack-bundle-analyzer\`) для контролю розміру.\\n- Пишіть тести для критичних частин процесу збирання, якщо це можливо.\\nВисновок: Кастомне налаштування збирача — потужний, але ризикований інструмент. Його варто застосовувати, коли стандартні засоби не покривають специфічних вимог проєкту (наприклад, особлива обробка асетів, кастомне розділення коду). У більшості випадків краще покладатися на перевірені шаблони та мінімально необхідні зміни.","module.exports = {\\n  // ...\\n  optimization: {\\n    // Проблема: splitChunks налаштовано надто агресивно,\\n    // що може створити безліч дрібних чанків і погіршити завантаження.\\n    splitChunks: {\\n      chunks: 'all',\\n      minSize: 0 // Небезпечне налаштування – чанки можуть бути надто маленькими.\\n    },\\n    // Проблема: вимкнено мініфікування для продакшену.\\n    minimize: false\\n  },\\n  module: {\\n    rules: [\\n      {\\n        test: /\\\\.js$/,\\n        // Проблема: виключення node_modules може зламати tree shaking\\n        // для деяких бібліотек.\\n        exclude: /node_modules/,\\n        use: 'babel-loader'\\n      }\\n    ]\\n  },\\n  plugins: [\\n    // Проблема: кілька плагінів можуть дублювати функціонал\\n    // або конфліктувати.\\n    new SomeCustomPlugin(),\\n    new SomeOtherPlugin()\\n  ]\\n};"],[3134,"Мікрофронтенди — це архітектурний стиль, за якого вебінтерфейс розбивається на незалежні, автономні частини, які можуть розробляти, розгортати й масштабувати окремі команди. Основна мета — подолати обмеження монолітного фронтенду у великих проєктах, дозволивши командам працювати незалежно з різними технологіями. Ключові підходи включають збирання на етапі збирання (build-time), інтеграцію на стороні сервера (server-side) та інтеграцію на стороні клієнта (client-side) з використанням таких інструментів, як Webpack Module Federation або фреймворків на кшталт single-spa. Це підвищує швидкість розробки й спрощує підтримку великих застосунків.","Мікрофронтенди — це підхід до розробки фронтенду, натхненний мікросервісною архітектурою. Замість одного великого монолітного застосунку інтерфейс розбивається на невеликі, слабко пов'язані частини — «мікрофронтенди». Кожна частина відповідає за певну бізнес-можливість (наприклад, каталог товарів, кошик, профіль користувача) і може розроблятися окремою командою зі своїм стеком технологій, процесом збирання та циклом розгортання.\\n\\nОсновні підходи до реалізації\\n\\nІснує кілька стратегій інтеграції мікрофронтендів у єдиний застосунок:\\n\\n- Збирання на етапі збирання (Build-time): Окремі мікрофронтенди публікують як пакети (наприклад, npm), а основний застосунок включає їх як залежності й збирає все разом. Це просто, але потребує перезбирання всього застосунку під час оновлення будь-якого мікрофронтенду.\\n\\n- Інтеграція на стороні сервера (Server-side): Сервер (наприклад, за допомогою Nginx або спеціального компонувальника) збирає HTML-фрагменти від різних мікрофронтендів в одну сторінку. Це покращує продуктивність, але додає складність на сервері.\\n\\n- Інтеграція на стороні клієнта (Client-side): Це найпопулярніший підхід. Основний застосунок («оболонка», або shell) динамічно завантажує й рендерить мікрофронтенди під час виконання в браузері. Це забезпечує максимальну незалежність розгортання.\\n\\nПопулярні інструменти та технології\\n\\nДля клієнтської інтеграції часто використовують:\\n\\n- Webpack Module Federation: Дозволяє одному застосунку динамічно завантажувати код з іншого під час виконання. Це стало стандартом де-факто.\\n\\n- single-spa: Мета-фреймворк, який координує завантаження й рендеринг мікрофронтендів, написаних на різних технологіях (React, Vue, Angular).\\n\\n- Web Components: Використання нативних браузерних стандартів для створення інкапсульованих компонентів, які можна вбудовувати в будь-який застосунок.\\n\\nПриклад коду з Webpack Module Federation\\n\\nКонфігурація основного застосунку (host) і віддаленого мікрофронтенду (remote).\\n\\nДе застосовують\\n\\nМікрофронтенди особливо корисні у великих компаніях із кількома командами фронтенд-розробників, що працюють над одним продуктом (наприклад, маркетплейси, банківські застосунки, корпоративні портали). Вони дозволяють пришвидшити розробку, ізолювати ризики й поступово модернізувати легасі-код.\\n\\nВисновок: Архітектуру мікрофронтендів варто застосовувати для великих, довгоживучих вебзастосунків, де незалежність команд і частота розгортань є критично важливими факторами. Для невеликих проєктів або застосунків з однією командою складність цієї архітектури може переважити її переваги.","// webpack.config.js основного застосунку (host)\\nconst ModuleFederationPlugin = require('webpack/lib/container/ModuleFederationPlugin');\\n\\nmodule.exports = {\\n  plugins: [\\n    new ModuleFederationPlugin({\\n      name: 'hostApp',\\n      remotes: {\\n        // Указуємо, де шукати віддалений модуль\\n        mfCart: 'cartApp@http://localhost:3001/remoteEntry.js',\\n      },\\n      shared: ['react', 'react-dom'], // Спільні залежності\\n    }),\\n  ],\\n};\\n\\n// У коді основного застосунку React-компонент завантажується динамічно\\nconst RemoteCart = React.lazy(() => import('mfCart/CartComponent'));\\n\\nfunction App() {\\n  return (\\n    <div>\\n      <h1>Магазин</h1>\\n      <React.Suspense fallback={<div>Завантаження…</div>}>\\n        <RemoteCart />\\n      </React.Suspense>\\n    </div>\\n  );\\n}"],[3135,"Webpack оптимізує повторне використання бібліотек насамперед через створення окремого «вендорного» чанка (vendor chunk). Він виносить сторонні бібліотеки (наприклад, React, Lodash) з основного коду застосунку в окремий файл. Це дозволяє браузеру кешувати цей файл надовго, оскільки бібліотеки змінюються рідко. Під час оновлення коду застосунку користувачеві потрібно завантажувати лише змінений основний чанк, а бібліотеки беруться з кешу, що пришвидшує повторні відвідування.","Webpack використовує кілька стратегій для оптимізації повторного використання бібліотек, основна з яких — розділення коду (code splitting). Мета — відокремити код сторонніх залежностей (бібліотек), що рідко змінюється, від коду самого застосунку, що змінюється часто.\\n\\nСтворення Vendor Chunk\\n\\nНайпоширеніший підхід — налаштувати розділення так, щоб усі модулі з папки \`node_modules\` потрапляли в окремий бандл, який часто називають \`vendor.js\` або \`vendors~main.js\`. Це роблять за допомогою налаштування точки входу або плагіна \`SplitChunksPlugin\`.\\n\\nЯк це працює й де застосовують\\n\\nПід час збирання Webpack аналізує граф залежностей. Усі модулі, що відповідають правилу (наприклад, ті, що перебувають у \`node_modules\`), поміщаються в окремий чанк. На практиці це означає, що бібліотеки на кшталт React, Vue або Lodash буде завантажено один раз під час першого відвідування сайту й збережено в кеші браузера. Під час наступних оновлень функціональності застосунку (і зміни основного чанка) браузеру не потрібно завантажувати ці бібліотеки знову — вони беруться з кешу. Це критично важливо для великих застосунків і підвищує швидкість завантаження для постійних користувачів.\\n\\nДодаткові оптимізації\\n\\n- Хешування імен файлів (hashing): Імена вихідних файлів включають хеш вмісту (наприклад, \`vendors.abc123.js\`). Якщо бібліотеки не змінювалися, хеш залишається попереднім, і браузер використовує закешовану версію.\\n\\n- Мініфікація та стискання: Код бібліотек мініфікується та стискається для зменшення обсягу передавання.\\n\\n- Tree Shaking: Для ES6-модулів Webpack може виключити невикористовуваний код із бібліотек, якщо вони це підтримують, роблячи vendor chunk ще меншим.\\n\\nВисновок: Такий підхід варто застосовувати практично в будь-якому проєкті середнього та великого розміру, що використовує Webpack. Він дає негайний виграш у продуктивності за рахунок довгострокового кешування бібліотек, що покращує користувацький досвід, особливо для користувачів, які повертаються.","// webpack.config.js\\nmodule.exports = {\\n  optimization: {\\n    splitChunks: {\\n      cacheGroups: {\\n        vendor: {\\n          test: /[\\\\\\\\/]node_modules[\\\\\\\\/]/,\\n          name: 'vendors',\\n          chunks: 'all',\\n        },\\n      },\\n    },\\n  },\\n};"],[3136,"Під час імпорту однієї функції може підтягнутися вся бібліотека, якщо збирач модулів (наприклад, Webpack) не може безпечно видалити невикористовуваний код. Це відбувається, коли модуль має побічні ефекти (side effects) під час імпорту, наприклад змінює глобальні змінні або виконує код. Також деякі бібліотеки не підтримують tree shaking через структуру експортів (наприклад, експорт через єдиний об'єкт). Щоб цього уникнути, потрібно використовувати бібліотеки з підтримкою ES-модулів і налаштовувати sideEffects у конфігурації збирача.","Коли ви імпортуєте одну функцію з бібліотеки, ви очікуєте, що в підсумковий бандл потрапить лише її код. Проте іноді підтягується вся бібліотека, що збільшує розмір застосунку. Це пов'язано з роботою збирачів модулів, таких як Webpack або Rollup, і їхньою здатністю виконувати «tree shaking» — видалення мертвого коду.\\nЯк працює tree shaking\\nTree shaking — це процес статичного аналізу імпортів та експортів в ES-модулях. Збирач визначає, які експорти справді використовуються, і виключає невикористовувані. Для цього код має бути написаний у форматі ES-модулів (import/export), оскільки він статично аналізований.\\nЧому tree shaking може не спрацювати\\n\\n- Побічні ефекти (side effects): Якщо модуль виконує дії під час імпорту (наприклад, реєструє поліфіли або змінює глобальний об'єкт), збирач не може його видалити, оскільки це може зламати застосунок. У конфігурації Webpack потрібно явно вказати \`sideEffects: false\` для бібліотек без побічних ефектів.\\n- CommonJS-модулі: Бібліотеки, що експортуються через \`module.exports\`, завантажуються динамічно, що утруднює аналіз. Збирачі часто не можуть видалити невикористовуваний код із таких модулів.\\n- Структура експортів: Якщо бібліотека експортує всі функції через єдиний об'єкт (наприклад, \`import _ from 'lodash'\`), то навіть за використання однієї функції може підтягнутися весь модуль. Сучасні версії бібліотек часто підтримують модульні імпорти (наприклад, \`import debounce from 'lodash/debounce'\`).\\nПриклад коду й налаштування\\nРозглянемо приклад із бібліотекою, яка не підтримує tree shaking через побічні ефекти:\\n\\nПід час імпорту лише \`add\` збирач може включити весь модуль, оскільки є побічний ефект. Щоб це виправити, потрібно винести побічні ефекти в окремий модуль або вказати в package.json бібліотеки:\\n\\nПрактичні рекомендації\\n\\n- Використовуйте бібліотеки, які підтримують ES-модулі та tree shaking (наприклад, ES-версію Lodash).\\n- Налаштовуйте \`sideEffects\` у конфігурації Webpack або в package.json.\\n- Перевіряйте розмір бандла за допомогою інструментів на кшталт Webpack Bundle Analyzer.\\nВисновок: Tree shaking — потужний метод оптимізації, але він потребує коректної структури коду й налаштування збирача. Застосовуйте його для зменшення розміру бандла в production-збираннях, особливо у великих застосунках із багатьма залежностями.","// mathUtils.js\\nexport function add(a, b) {\\n  return a + b;\\n}\\nexport function multiply(a, b) {\\n  return a * b;\\n}\\n// Побічний ефект: зміна глобальної змінної\\nwindow.myLib = { version: '1.0' };\\n\\n{\\n  \\"name\\": \\"my-lib\\",\\n  \\"sideEffects\\": false\\n}"],[3137,"Для налаштування збирання фронтенду використовують бандлери, такі як Webpack, Vite або Parcel. Основні підходи включають розділення коду (code splitting), мініфікацію, транспіляцію через Babel, керування асетами та налаштування dev-сервера. Також застосовують лоадери та плагіни для обробки різних типів файлів. Важливо налаштовувати режими розробки та продакшену окремо.","Основні підходи до налаштування збирання фронтенду\\nЗбирання фронтенду — це процес перетворення вихідного коду (JS, CSS, зображення) в оптимізований набір файлів для браузера. Основні інструменти: Webpack, Vite, Parcel, Rollup. Кожен із них пропонує свої підходи до конфігурації.\\nКлючові концепції\\n\\n- Entry і Output: точка входу й папка для зібраних файлів.\\n- Loaders: обробляють файли (наприклад, babel-loader для JS, css-loader для CSS).\\n- Plugins: розширюють функціональність (наприклад, HtmlWebpackPlugin для генерації HTML).\\n- Code Splitting: розділення коду на чанки для лінивого завантаження.\\n- Module Federation: дозволяє завантажувати модулі з інших збирань (мікрофронтенди).\\nПриклад конфігурації Webpack\\n\\nВисновок\\nНалаштування збирання фронтенду необхідне для оптимізації продуктивності, зменшення розміру бандла та покращення досвіду розробки. Використовуйте Webpack для складних проєктів із мікрофронтендами, Vite для швидкої розробки, а Parcel для простих конфігурацій без зайвих налаштувань.","const path = require('path');\\nconst HtmlWebpackPlugin = require('html-webpack-plugin');\\n\\nmodule.exports = {\\n  entry: './src/index.js',\\n  output: {\\n    path: path.resolve(__dirname, 'dist'),\\n    filename: '[name].[contenthash].js',\\n  },\\n  module: {\\n    rules: [\\n      { test: /\\\\.js$/, exclude: /node_modules/, use: 'babel-loader' },\\n      { test: /\\\\.css$/, use: ['style-loader', 'css-loader'] },\\n    ],\\n  },\\n  plugins: [new HtmlWebpackPlugin({ template: './src/index.html' })],\\n  optimization: {\\n    splitChunks: { chunks: 'all' },\\n  },\\n};"],[3138,"PostCSS — це інструмент для трансформації CSS за допомогою плагінів. Для кросбраузерності використовують плагін Autoprefixer, який додає вендорні префікси на основі даних Can I Use. Це позбавляє розробника ручного написання префіксів і спрощує підтримку старих браузерів.","Що таке PostCSS і як він працює\\nPostCSS — це інструмент, який перетворює CSS за допомогою плагінів на JavaScript. Він не є препроцесором на кшталт Sass або Less, а скоріше платформою для обробки стилів. Основна ідея — розбити CSS на абстрактне синтаксичне дерево (AST), застосувати до нього плагіни та згенерувати новий CSS.\\nРоль у кросбраузерності\\nДля забезпечення кросбраузерності ключовим плагіном є Autoprefixer. Він аналізує CSS і додає вендорні префікси (наприклад, \`-webkit-\`, \`-moz-\`) на основі даних із сервісу Can I Use. Це автоматизує процес, який раніше виконувався вручну або за допомогою препроцесорів.\\nПриклад використання\\n\\nІнші корисні плагіни\\n\\n- cssnano — мініфікація CSS для продакшену.\\n- PostCSS Preset Env — дозволяє використовувати сучасні CSS-функції (наприклад, \`custom properties\`), перетворюючи їх на сумісні аналоги.\\n- Stylelint — лінтинг CSS для дотримання стандартів.\\nВисновок\\nPostCSS з Autoprefixer — це стандартний інструмент для автоматизації кросбраузерності в сучасних проєктах. Він спрощує підтримку старих браузерів, зменшує ручну роботу й інтегрується у збирачі (Webpack, Gulp). Рекомендується використовувати в будь-якому проєкті, де важлива сумісність із різними браузерами.","/* Вихідний CSS */\\n.example {\\n  display: flex;\\n  transition: all 0.3s;\\n}\\n\\n/* Після обробки Autoprefixer */\\n.example {\\n  display: -webkit-box;\\n  display: -ms-flexbox;\\n  display: flex;\\n  -webkit-transition: all 0.3s;\\n  -o-transition: all 0.3s;\\n  transition: all 0.3s;\\n}"],[3139,"Мікрофронтенди — це архітектурний підхід, за якого фронтенд-застосунок розбивається на незалежні, слабко пов'язані модулі. Кожен модуль розробляють, тестують і розгортають окремо, що дозволяє командам працювати паралельно. Це покращує масштабованість і спрощує підтримку великих проєктів.","Що таке мікрофронтенди?\\nМікрофронтенди — це архітектурний стиль, за якого інтерфейс вебзастосунку розбивається на невеликі, незалежні частини, кожна з яких відповідає за свою функціональність. Цей підхід запозичує ідеї з мікросервісної архітектури на бекенді, але застосовує їх до фронтенду. Основна мета — уникнути монолітного фронтенду, який складно підтримувати й масштабувати.\\nЯк це працює?\\nКожен мікрофронтенд являє собою окремий застосунок, який може бути написаний на різних фреймворках (React, Vue, Angular) і яким керує своя команда. Інтеграція відбувається на рівні браузера за допомогою таких технік, як iframe, Web Components або спеціальні фреймворки (наприклад, Module Federation у Webpack 5).\\nПриклад інтеграції через Module Federation\\n\\nУ головному застосунку можна динамічно завантажувати цей компонент:\\n\\nПереваги та недоліки\\n\\n- Переваги: незалежна розробка, ізольоване розгортання, технологічна гнучкість, покращена масштабованість.\\n- Недоліки: складність інтеграції, збільшення розміру бандла, потреба в єдиній системі дизайну, потенційні проблеми з продуктивністю.\\nВисновок: Мікрофронтенди варто застосовувати у великих проєктах із кількома командами, де важлива незалежність розробки та розгортання. Для невеликих застосунків цей підхід може бути надлишковим через додаткову складність.","// webpack.config.js для мікрофронтенда\\nconst ModuleFederationPlugin = require('webpack/lib/container/ModuleFederationPlugin');\\n\\nmodule.exports = {\\n  plugins: [\\n    new ModuleFederationPlugin({\\n      name: 'app1',\\n      filename: 'remoteEntry.js',\\n      exposes: {\\n        './Header': './src/Header',\\n      },\\n      shared: ['react', 'react-dom'],\\n    }),\\n  ],\\n};\\n\\n// Головний застосунок\\nconst Header = React.lazy(() => import('app1/Header'));\\n\\nfunction App() {\\n  return (\\n    <React.Suspense fallback={<div>Loading...</div>}>\\n      <Header />\\n    </React.Suspense>\\n  );\\n}"],[3140,"Так, значення змінних оточення, які використовуються в коді, потрапляють у підсумковий bundle, якщо вони підставляються на етапі збирання. Це може призвести до витоку чутливих даних, таких як API-ключі або секрети. Тому важливо не зберігати секретів у клієнтському коді й використовувати серверні змінні оточення.","Як змінні оточення потрапляють у bundle\\nЗмінні оточення (environment variables) — це значення, які передаються застосунку під час виконання. У процесі збирання (наприклад, за допомогою Webpack або Vite) ці змінні можуть бути підставлені безпосередньо в код. Якщо змінна використовується в клієнтському коді, її значення буде вбудовано в підсумковий bundle, який надсилається браузеру.\\nПриклад з Webpack\\nРозглянемо приклад із використанням Webpack і плагіна \`DefinePlugin\`:\\n\\nПісля збирання в bundle буде вставлено значення змінної, наприклад \`https://api.example.com\`. Це означає, що будь-який користувач може побачити це значення, відкривши вихідний код застосунку в браузері.\\nРизики безпеки\\nЯкщо у змінних оточення зберігаються секрети (наприклад, ключі доступу до бази даних або токени), вони стануть доступними всім, хто завантажить ваш застосунок. Тому ніколи не слід передавати в клієнтський код чутливі дані. Використовуйте серверні змінні оточення для секретів і передавайте лише ті дані, які необхідні для роботи клієнта (наприклад, публічні API-ключі).\\nВисновок\\nЗмінні оточення, які використовуються в клієнтському коді, потрапляють у підсумковий bundle і стають видимими для користувачів. Це нормально для публічних даних, але недопустимо для секретів. Для безпечної роботи використовуйте серверні змінні оточення й передавайте лише необхідні публічні значення.","// webpack.config.js\\nconst webpack = require('webpack');\\n\\nmodule.exports = {\\n  plugins: [\\n    new webpack.DefinePlugin({\\n      'process.env.API_URL': JSON.stringify(process.env.API_URL)\\n    })\\n  ]\\n};\\n\\n// У коді застосунку\\nconst apiUrl = process.env.API_URL;\\nconsole.log(apiUrl); // Після збирання буде замінено на фактичне значення"],[3141,"Змінні оточення підставляються на етапі збирання за допомогою спеціальних інструментів, наприклад DefinePlugin у Webpack. Вони замінюються на їхні значення прямо в коді до виконання. Це дозволяє використовувати різні конфігурації для різних середовищ без зміни вихідного коду.","Як працює підстановка змінних оточення на етапі збирання\\nПідстановка змінних оточення (environment variables) під час збирання — це процес заміни спеціальних маркерів у вихідному коді на фактичні значення, які відомі на момент компіляції або збирання застосунку. Це дозволяє створювати різні збирання для різних середовищ (розробка, тестування, продакшн) без зміни самого коду.\\nОсновні механізми\\n\\n- Webpack DefinePlugin: Дозволяє створювати глобальні константи, які замінюються на етапі компіляції. Наприклад, \`process.env.NODE_ENV\` може бути замінено на \`\\"production\\"\`.\\n- Vite define: Аналогічний механізм, де змінні задають через конфігурацію й підставляють у код.\\n- Docker build args: Під час збирання Docker-образу можна передавати аргументи, які будуть використані в Dockerfile.\\nПриклад з Webpack\\n\\nПрактичне застосування\\nЦей підхід широко використовують для:\\n\\n- Налаштування URL API для різних середовищ.\\n- Увімкнення або вимкнення зневаджувальних функцій.\\n- Керування ключами доступу до сторонніх сервісів (але не для секретів!).\\nВажливо пам'ятати, що змінні оточення, підставлені на етапі збирання, стають частиною підсумкового бандла й видні в клієнтському коді. Тому не варто використовувати цей механізм для зберігання секретних даних (паролів, токенів). Для цього краще використовувати серверні змінні оточення.\\nВисновок: Підстановка змінних оточення на етапі збирання — це потужний інструмент для конфігурації застосунків під різні середовища, який підвищує гнучкість і безпеку, якщо використовується правильно.","// webpack.config.js\\nconst webpack = require('webpack');\\n\\nmodule.exports = {\\n  plugins: [\\n    new webpack.DefinePlugin({\\n      'process.env.API_URL': JSON.stringify('https://api.example.com'),\\n      'process.env.NODE_ENV': JSON.stringify('production')\\n    })\\n  ]\\n};\\n\\n// У коді застосунку\\nconsole.log(process.env.API_URL); // Після збирання: 'https://api.example.com'"],[3142,"CSS-модулі вирішують проблему колізії імен класів, автоматично генеруючи унікальні імена класів на етапі збирання. Кожен клас із CSS-файлу перетворюється на хешований рядок, який гарантовано унікальний у межах усього застосунку. Це дозволяє розробникам використовувати короткі та зрозумілі імена без ризику перетину з іншими компонентами.","Як CSS-модулі вирішують проблему колізії імен класів\\nCSS-модулі — це підхід, за якого стилі компонента ізолюються на рівні збирання. Основна проблема, яку вони вирішують, — глобальний простір імен CSS, де два однакові класи з різних файлів можуть конфліктувати. CSS-модулі автоматично генерують унікальні імена класів, додаючи до них хеш або інший ідентифікатор, що виключає колізії.\\nПринцип роботи\\nНа етапі збирання (наприклад, за допомогою Webpack і css-loader) кожен CSS-файл обробляється як модуль. Усі імена класів у ньому перетворюються на унікальні рядки, а в JavaScript-коді імпортуються як об'єкт, де ключ — вихідне ім'я, а значення — згенероване. Це дозволяє використовувати короткі імена в розробці, але гарантує унікальність у рантаймі.\\nПриклад коду\\n\\nДе застосовують\\n\\n- У React, Vue, Angular та інших фреймворках для ізоляції стилів компонентів.\\n- У проєктах із великою кодовою базою, де важливо уникнути випадкових перевизначень.\\n- Під час використання CSS-препроцесорів (Sass, Less) у поєднанні з модулями.\\nВисновок\\nCSS-модулі варто застосовувати в будь-якому сучасному вебпроєкті, де використовується компонентний підхід. Вони забезпечують передбачуваність стилів, спрощують рефакторинг і усувають головний біль від глобальних CSS-конфліктів, особливо в командах.","// styles.module.css\\n.button {\\n  background: blue;\\n  color: white;\\n}\\n\\n// Component.jsx\\nimport styles from './styles.module.css';\\n\\nfunction Button() {\\n  return <button className={styles.button}>Click me</button>;\\n}\\n\\n// У браузері клас буде виглядати як \\"_button_1a2b3\\""],[3143,"Щоб додати підтримку CSS-препроцесора, наприклад Sass, потрібно встановити відповідні завантажувачі: sass-loader, css-loader і style-loader. Потім у конфігурації Webpack у розділі module.rules додати правило для файлів .scss, указавши ці завантажувачі в порядку справа наліво. Це дозволить Webpack обробляти Sass-файли, перетворювати їх на CSS і вносити в HTML.","Як додати підтримку CSS-препроцесорів у Webpack\\nCSS-препроцесори, такі як Sass, Less або Stylus, розширюють можливості звичайного CSS, додаючи змінні, вкладеність, міксини та інші функції. Щоб Webpack міг обробляти файли цих препроцесорів, необхідно налаштувати відповідні завантажувачі (loaders). Завантажувачі — це модулі, які перетворюють файли перед додаванням у бандл.\\nВстановлення необхідних пакетів\\nДля роботи з Sass (найпопулярнішим препроцесором) знадобляться три пакети:\\n\\n- \`sass-loader\` — компілює Sass/SCSS у CSS.\\n- \`css-loader\` — інтерпретує \`@import\` і \`url()\` у CSS.\\n- \`style-loader\` — вносить CSS у DOM через тег \`<style>\`.\\nВстановлення виконується командою:\\n\\nНалаштування конфігурації Webpack\\nУ файлі \`webpack.config.js\` додаємо правило для файлів із розширенням \`.scss\` або \`.sass\`:\\n\\nПорядок завантажувачів важливий: Webpack застосовує їх справа наліво. Спершу \`sass-loader\` перетворює SCSS у CSS, потім \`css-loader\` обробляє CSS, і нарешті \`style-loader\` додає стилі в HTML.\\nПриклад використання\\nПісля налаштування можна імпортувати SCSS-файли в JavaScript:\\n\\nWebpack автоматично обробить файл і додасть стилі на сторінку.\\nВисновок\\nНалаштування підтримки CSS-препроцесорів у Webpack — це стандартне завдання для сучасних фронтенд-проєктів. Воно дозволяє використовувати потужні можливості препроцесорів, зберігаючи автоматизацію збирання. Цей підхід застосовують у більшості React, Vue та інших SPA-застосунків для спрощення роботи зі стилями.","npm install --save-dev sass-loader sass css-loader style-loader\\n\\nmodule.exports = {\\n  module: {\\n    rules: [\\n      {\\n        test: /\\\\.scss$/,\\n        use: [\\n          'style-loader',\\n          'css-loader',\\n          'sass-loader'\\n        ]\\n      }\\n    ]\\n  }\\n};\\n\\nimport './styles.scss';\\n\\nconst element = document.createElement('div');\\nelement.className = 'container';\\ndocument.body.appendChild(element);"],[3144,"Для невеликого React-проєкту з корпоративними стандартами найкраще використовувати Webpack, оскільки він є найгнучкішим і найналаштовуванішим збирачем. Він підтримує React з коробки через Babel і дозволяє легко інтегрувати будь-які плагіни та лоадери. Якщо в компанії вже є готові конфігурації або шаблони, Webpack забезпечить їхню сумісність. Альтернативи на кшталт Vite або Parcel можуть бути простішими, але можуть не відповідати внутрішнім стандартам.","Вибір збирача для React-проєкту\\nПід час вибору збирача для невеликого React-проєкту в умовах корпоративних стандартів ключовим фактором стає сумісність з наявною інфраструктурою. Webpack є де-факто стандартом у великих компаніях завдяки своїй гнучкості та широкій екосистемі плагінів. Він дозволяє точно налаштувати процес збирання під будь-які вимоги, включно з оптимізацією, розділенням коду та підтримкою застарілих браузерів.\\nПрактичний приклад конфігурації Webpack для React\\n\\nЧому Webpack, а не альтернативи\\n\\n- Сумісність зі стандартами: Webpack легко адаптується під наявні корпоративні конфігурації, ESLint, Prettier та інші інструменти.\\n- Гнучкість: Можливість тонкого налаштування через лоадери та плагіни для роботи з TypeScript, CSS Modules, зображеннями та шрифтами.\\n- Продуктивність: Вбудовані оптимізації, такі як tree shaking і code splitting, критичні для production-збирань.\\nХоча Vite пропонує швидшу розробку за рахунок ESM, він може не підтримувати специфічних корпоративних плагінів або потребувати додаткового налаштування для сумісності. Parcel, у свою чергу, надто автоматизований і не дає достатнього контролю.\\nВисновок\\nДля невеликого React-проєкту в компанії зі сталими стандартами Webpack залишається оптимальним вибором завдяки своїй гнучкості, зрілості та сумісності з наявними інструментами. Він забезпечує повний контроль над збиранням і легко інтегрується в будь-яке корпоративне середовище.","// webpack.config.js\\nconst path = require('path');\\nconst HtmlWebpackPlugin = require('html-webpack-plugin');\\n\\nmodule.exports = {\\n  entry: './src/index.js',\\n  output: {\\n    path: path.resolve(__dirname, 'dist'),\\n    filename: 'bundle.js',\\n  },\\n  module: {\\n    rules: [\\n      {\\n        test: /\\\\.jsx?$/,\\n        exclude: /node_modules/,\\n        use: {\\n          loader: 'babel-loader',\\n          options: {\\n            presets: ['@babel/preset-env', '@babel/preset-react'],\\n          },\\n        },\\n      },\\n      {\\n        test: /\\\\.css$/,\\n        use: ['style-loader', 'css-loader'],\\n      },\\n    ],\\n  },\\n  plugins: [\\n    new HtmlWebpackPlugin({\\n      template: './public/index.html',\\n    }),\\n  ],\\n  resolve: {\\n    extensions: ['.js', '.jsx'],\\n  },\\n};"],[3145,"Для аналізу розміру бандла використовують інструменти на кшталт Webpack Bundle Analyzer, які візуалізують склад збирання. Зменшити розмір можна за допомогою tree shaking (видалення невикористовуваного коду), code splitting (розділення коду на чанки), мініфікації (стискання коду) та оптимізації залежностей (заміна важких бібліотек на легкі аналоги). Також допомагає ліниве завантаження модулів і видалення дублікатів залежностей.","Аналіз розміру бандла\\nДля аналізу розміру бандла у Webpack використовують плагін \`webpack-bundle-analyzer\`, який створює інтерактивну карту, що показує, які модулі займають найбільше місця. Це допомагає виявити неоптимальні залежності або дублікати коду.\\nМетоди зменшення розміру\\n\\n- Tree Shaking: видаляє невикористовуваний код під час збирання. Для цього використовуйте ES-модулі (\`import/export\`) і налаштуйте \`sideEffects: false\` у \`package.json\`.\\n- Code Splitting: розділяє код на окремі чанки, які завантажуються на вимогу. Реалізується через динамічний імпорт: \`import('./module').then(...)\`.\\n- Мініфікація: стискає код, видаляючи пробіли, коментарі та перейменовуючи змінні. У Webpack використовується \`TerserPlugin\`.\\n- Оптимізація залежностей: замініть важкі бібліотеки (наприклад, moment.js) на легкі аналоги (date-fns) або використовуйте лише потрібні частини.\\nПриклад налаштування Webpack\\n\\nТакож корисно налаштувати \`externals\` для винесення бібліотек (наприклад, React) у CDN, якщо вони не змінюються.\\nВисновок: Аналіз і зменшення розміру бандла критичні для пришвидшення завантаження застосунку, особливо на повільних з'єднаннях. Застосовуйте ці методи в production-збираннях для оптимізації користувацького досвіду.","// webpack.config.js\\nconst BundleAnalyzerPlugin = require('webpack-bundle-analyzer').BundleAnalyzerPlugin;\\n\\nmodule.exports = {\\n  mode: 'production',\\n  optimization: {\\n    usedExports: true, // tree shaking\\n    splitChunks: {\\n      chunks: 'all', // code splitting\\n    },\\n    minimize: true,\\n    minimizer: [new TerserPlugin()],\\n  },\\n  plugins: [\\n    new BundleAnalyzerPlugin(),\\n  ],\\n};"],[3146,"Транзитивні залежності — це залежності, які потрібні не напряму вашому проєкту, а його прямим залежностям. Наприклад, якщо ваш проєкт використовує бібліотеку A, а бібліотека A використовує бібліотеку B, то B є транзитивною залежністю. Менеджери пакетів, такі як npm або Maven, автоматично розв'язують і підключають такі залежності. Це спрощує розробку, але може призвести до конфліктів версій або роздування проєкту.","Що таке транзитивні залежності?\\nТранзитивні залежності — це бібліотеки або пакети, які не вказані напряму у вашому проєкті, але потрібні для роботи його прямих залежностей. Уявіть, що ви будуєте дім і купуєте готові двері (пряма залежність). Для встановлення цих дверей потрібні петлі та ручка — це транзитивні залежності. Ви їх не замовляли окремо, але вони необхідні для роботи дверей.\\nЯк це працює на практиці?\\nМенеджери пакетів (npm, Maven, pip) автоматично будують дерево залежностей. Коли ви додаєте пакет A, система перевіряє його власні залежності (наприклад, B і C) і підключає їх рекурсивно. Це позбавляє розробника ручного пошуку всіх допоміжних бібліотек.\\nПриклад з npm\\n\\nПроблеми та керування\\n\\n- Конфлікти версій: Дві різні прямі залежності можуть потребувати різних версій однієї транзитивної бібліотеки. Менеджери пакетів намагаються розв'язати це, вибираючи сумісну версію або дублюючи пакет.\\n- Розмір проєкту: Безліч транзитивних залежностей може сильно збільшити розмір node_modules або підсумкового артефакту.\\n- Уразливості: Транзитивні залежності можуть містити уразливості, які ви не контролюєте напряму. Інструменти на кшталт npm audit допомагають їх відстежувати.\\nВисновок\\nТранзитивні залежності — це невід'ємна частина сучасної розробки, яка автоматизує керування бібліотеками. Проте важливо слідкувати за їхніми версіями та кількістю, щоб уникнути конфліктів і проблем безпеки. Використовуйте lock-файли (package-lock.json) і регулярно оновлюйте залежності.","// package.json вашого проєкту\\n{\\n  \\"dependencies\\": {\\n    \\"express\\": \\"^4.18.0\\"\\n  }\\n}\\n\\n// express має свої залежності, наприклад accepts, array-flatten\\n// Вони стають транзитивними для вашого проєкту\\n\\n// Після npm install у node_modules з'явиться:\\n// node_modules/express\\n// node_modules/accepts (транзитивна)\\n// node_modules/array-flatten (транзитивна)"],[3147,"Детермінована установка залежностей гарантує, що за однакових вхідних даних (файл маніфесту) кожного разу буде отримано однаковий набір пакетів з однаковими версіями. Цього досягають за допомогою lock-файлів (наприклад, package-lock.json або yarn.lock), які фіксують точні версії всіх залежностей і їхніх підзалежностей. Такий підхід запобігає неочікуваним змінам у проєкті через вихід нових версій пакетів і забезпечує ідентичність оточення на всіх машинах розробників і в CI/CD.","Що таке детермінована установка залежностей?\\nДетермінована установка залежностей — це процес, за якого менеджер пакетів (наприклад, npm, Yarn, pip) гарантує, що для того самого набору вхідних даних (файл маніфесту, наприклад package.json) буде отримано ідентичний набір установлених пакетів з однаковими версіями. Це означає, що результат установки передбачуваний і відтворюваний на будь-якій машині.\\nДля чого це потрібно?\\nБез детермінізму розробники можуть зіткнутися із ситуацією, коли проєкт працює на одній машині, але ламається на іншій через незначні відмінності у версіях залежностей. Це особливо критично в командній роботі та під час розгортання в production. Детермінована установка забезпечує:\\n\\n- Відтворюваність збирань: кожного разу виходить однакове оточення.\\n- Стабільність: нові версії пакетів не ламають проєкт неочікувано.\\n- Безпеку: можна контролювати, які саме версії використовуються.\\nЯк це реалізується?\\nОсновний механізм — це lock-файли. Наприклад, в екосистемі JavaScript використовують package-lock.json (npm) або yarn.lock (Yarn). Ці файли містять точні версії всіх залежностей і їхніх підзалежностей, а також хеші для перевірки цілісності. Приклад вмісту package-lock.json:\\n\\nПід час установки менеджер пакетів спершу перевіряє наявність lock-файлу. Якщо він є, то використовує версії з нього, ігноруючи діапазони версій, указані в маніфесті. Якщо lock-файлу немає, він створюється на основі розв'язаних версій.\\nПрактичний приклад\\nПрипустимо, у package.json указано залежність \\"lodash\\": \\"^4.17.0\\". Без lock-файлу під час установки може бути завантажено версію 4.17.21 сьогодні і 4.18.0 завтра, якщо вона вийде. З lock-файлом завжди буде встановлено версію, зафіксовану в ньому, наприклад 4.17.21.\\nВисновок\\nДетермінована установка залежностей — це фундаментальна практика для забезпечення надійності та передбачуваності розробки. Вона обов'язкова в будь-якому проєкті, де важлива стабільність оточення, особливо в командній роботі та CI/CD. Використання lock-файлів і їхній коміт у репозиторій — стандарт індустрії.","{\\n  \\"name\\": \\"my-project\\",\\n  \\"lockfileVersion\\": 2,\\n  \\"packages\\": {\\n    \\"node_modules/express\\": {\\n      \\"version\\": \\"4.18.2\\",\\n      \\"resolved\\": \\"https://registry.npmjs.org/express/-/express-4.18.2.tgz\\",\\n      \\"integrity\\": \\"sha512-...\\"\\n    }\\n  }\\n}"],[3148,"У Maven існують scope: compile (за замовчуванням), provided, runtime, test, system та import. Scope provided означає, що залежність потрібна для компіляції, але не буде включена в підсумковий артефакт, оскільки передбачається, що її надасть середовище виконання (наприклад, сервлет-контейнер). Це корисно для бібліотек, які вже є на сервері, щоб уникнути конфліктів і зменшити розмір застосунку.","Області видимості (scope) у Maven\\nКрім стандартних compile, test і runtime, Maven надає scope: provided, system та import. Кожен із них визначає, на якому етапі збирання залежність доступна й чи буде вона включена в підсумковий артефакт.\\nScope provided\\nScope provided указує, що залежність потрібна для компіляції, але не має упаковуватися в підсумковий JAR/WAR, оскільки передбачається, що її надасть середовище виконання (наприклад, сервлет-контейнер, такий як Tomcat, або JDK). Це дозволяє уникнути дублювання бібліотек і конфліктів версій.\\nПриклад: під час розробки вебзастосунку на Java Servlet API звичайно вказують scope provided, оскільки сервлет-контейнер уже містить цю бібліотеку.\\n\\nІнші scope\\n\\n- system — схожий на provided, але шлях до JAR указують явно через системну змінну. Використовують рідко, оскільки це порушує переносимість.\\n- import — використовують лише в розділі <dependencyManagement> для імпорту залежностей з іншого POM (наприклад, BOM).\\nВисновок\\nScope provided застосовують для бібліотек, які вже є в середовищі виконання, щоб зменшити розмір артефакту й уникнути конфліктів. Це стандартна практика для сервлетів, JSP та інших API, які надає контейнер.","<dependency>\\n    <groupId>javax.servlet</groupId>\\n    <artifactId>javax.servlet-api</artifactId>\\n    <version>4.0.1</version>\\n    <scope>provided</scope>\\n</dependency>"],[3149,"Cache busting — це техніка, яка змушує браузер завантажувати нову версію статичного файлу (CSS, JS), ігноруючи старий кеш. Звичайно реалізується додаванням унікального хеша вмісту в ім'я файлу. Це гарантує, що користувачі побачать актуальну версію застосунку після деплою. Без cache busting браузер може показувати застарілі стилі або скрипти.","Що таке cache busting і для чого він потрібен\\nCache busting (скидання кешу) — це підхід, який використовують для примусового оновлення статичних ресурсів (JavaScript, CSS, зображення) у браузері користувача після виходу нової версії застосунку. Браузери активно кешують файли, щоб пришвидшити завантаження сторінок, але це може призвести до того, що користувачі побачать стару версію інтерфейсу або зламану функціональність після деплою.\\nЯк це працює\\nОсновна ідея — змінити ім'я файлу або додати до нього унікальний параметр за кожної зміни вмісту. Найнадійніший спосіб — використати хеш від вмісту файлу (content hash). Наприклад, файл \`main.js\` перетворюється на \`main.a1b2c3.js\`. Коли вміст змінюється, хеш стає іншим, і браузер сприймає це як новий ресурс, завантажуючи його заново.\\nПриклад реалізації з Webpack\\n\\nЗа кожного збирання Webpack обчислює хеш на основі вмісту файлу. Якщо код не змінювався — хеш залишається попереднім, і браузер використовує закешовану версію. Це оптимально: користувачі не завантажують ті самі файли повторно.\\nДе застосовують\\n\\n- Збирачі модулів (Webpack, Vite, Parcel) — автоматично додають хеші в імена файлів.\\n- CDN і сервери статики — для довгострокового кешування з можливістю швидкого оновлення.\\n- Будь-які вебзастосунки, де важлива актуальність інтерфейсу та продуктивність завантаження.\\nВисновок\\nCache busting — обов'язкова практика для production-збирань. Вона дозволяє поєднувати переваги кешування (швидке завантаження) з гарантією, що користувачі завжди отримують актуальні файли. Без неї часті баги, пов'язані із застарілими скриптами або стилями після деплою.","// webpack.config.js\\nmodule.exports = {\\n  output: {\\n    filename: '[name].[contenthash].js',\\n    path: path.resolve(__dirname, 'dist'),\\n  },\\n};\\n// Результат: main.8f3b2c.js, vendor.4a1d5e.js"],[3150,"CSS- і JavaScript-файли обробляються за допомогою завантажувачів (loaders) у Webpack. Для CSS використовують css-loader і style-loader, які перетворюють CSS на JavaScript-модулі та вносять стилі в DOM. Для JavaScript використовують babel-loader для транспіляції сучасного коду в старіші версії. Ці завантажувачі налаштовують у конфігурації Webpack.","Обробка CSS і JavaScript у Webpack\\nWebpack — це модульний збирач, який обробляє всі файли проєкту як модулі. Для обробки CSS і JavaScript використовують спеціальні завантажувачі (loaders), які перетворюють файли перед додаванням у підсумковий бандл.\\nОбробка CSS\\nДля CSS використовують два основні завантажувачі: \`css-loader\` і \`style-loader\`. \`css-loader\` інтерпретує \`@import\` і \`url()\` у CSS, перетворюючи його на JavaScript-модуль. \`style-loader\` потім вносить ці стилі в DOM через тег \`<style>\`. Як альтернативу можна використати \`MiniCssExtractPlugin\` для видобування CSS в окремі файли.\\n\\nОбробка JavaScript\\nДля JavaScript часто використовують \`babel-loader\`, який транспілює сучасний ES6+ код в ES5 для сумісності з браузерами. Babel використовує пресети, такі як \`@babel/preset-env\`, для визначення необхідних перетворень.\\n\\nЦі завантажувачі працюють послідовно: Webpack застосовує їх у порядку справа наліво (знизу вгору в масиві). Для CSS спершу застосовується \`css-loader\`, потім \`style-loader\`. Для JavaScript — \`babel-loader\`.\\nВисновок: Використання завантажувачів Webpack дозволяє автоматизувати обробку CSS і JavaScript, забезпечуючи сумісність та оптимізацію коду для продакшену.","// webpack.config.js\\nmodule.exports = {\\n  module: {\\n    rules: [\\n      {\\n        test: /\\\\.css$/,\\n        use: ['style-loader', 'css-loader']\\n      }\\n    ]\\n  }\\n};\\n\\n// webpack.config.js\\nmodule.exports = {\\n  module: {\\n    rules: [\\n      {\\n        test: /\\\\.js$/,\\n        exclude: /node_modules/,\\n        use: {\\n          loader: 'babel-loader',\\n          options: {\\n            presets: ['@babel/preset-env']\\n          }\\n        }\\n      }\\n    ]\\n  }\\n};"],[3151,"Source Map — це файл, який пов'язує згенерований (мініфікований або транспілований) код із вихідним кодом. Він дозволяє розробникам бачити та зневаджувати оригінальний код в інструментах розробника браузера, навіть якщо в production використовується стиснена версія. Source Map містить інформацію про відповідність рядків і символів між вихідним і підсумковим файлом.","Що таке Source Map?\\nSource Map — це технологія, яка дозволяє зіставити згенерований (наприклад, мініфікований, об'єднаний або транспілований) JavaScript-код із його вихідним кодом. Це критично важливо для зневадження в production-середовищі, де код звичайно стиснений і оптимізований, що робить його нечитним для людини.\\nЯк це працює?\\nКоли ви використовуєте збирач (наприклад, Webpack) або транспілятор (наприклад, Babel), він може створити додатковий файл із розширенням .map. Цей файл містить JSON-структуру, яка описує відповідність кожного рядка та символу у згенерованому коді вихідному коду. Браузер, завантажуючи такий .map файл (через спеціальний коментар у кінці згенерованого файлу), може в інструментах розробника показати оригінальний код, а не стиснений.\\nПриклад конфігурації Webpack\\n\\nУ цьому прикладі опція \`devtool: 'source-map'\` указує Webpack створювати окремий файл \`bundle.js.map\`. У production-збираннях часто використовують легші варіанти, наприклад \`'hidden-source-map'\` (щоб не розкривати вихідний код користувачам), або вимикають Source Map повністю.\\nДе застосовують?\\n\\n- Зневадження JavaScript/TypeScript у браузері.\\n- Зневадження CSS, згенерованого з препроцесорів (Sass, Less).\\n- Зневадження коду, написаного на TypeScript, CoffeeScript або інших мовах, що компілюються в JavaScript.\\nВисновок\\nSource Map — незамінний інструмент для комфортного зневадження сучасного фронтенду. Використовуйте його в development-збираннях завжди, а в production — з осторогою, щоб не розкрити вихідний код, або використовуйте приховані Source Map для внутрішнього моніторингу помилок.","// webpack.config.js\\nmodule.exports = {\\n  mode: 'development',\\n  entry: './src/index.js',\\n  output: {\\n    filename: 'bundle.js',\\n    path: path.resolve(__dirname, 'dist'),\\n  },\\n  devtool: 'source-map', // Увімкнює генерацію Source Map\\n};"],[3152,"Оптимізація збирання включає tree shaking для видалення невикористовуваного коду, code splitting для розділення бандла на частини, мініфікацію (наприклад, TerserPlugin) і стискання (gzip/Brotli). Також використовують динамічні імпорти, аналіз бандла (webpack-bundle-analyzer) і заміну великих бібліотек на легші аналоги.","Основні підходи до оптимізації збирання\\nОптимізація бандла спрямована на зменшення часу завантаження сторінки та покращення користувацького досвіду. Основні методи включають tree shaking, code splitting, мініфікацію та стискання.\\nTree Shaking\\nTree shaking видаляє невикористовуваний код із модулів. Для цього використовується статичний аналіз імпортів. У Webpack це працює з ES-модулями (import/export). Приклад:\\n\\nCode Splitting\\nCode splitting розділяє бандл на частини, які завантажуються на вимогу. Це зменшує початковий розмір завантаження. Використовується динамічний імпорт:\\n\\nМініфікація та стискання\\nМініфікація видаляє пробіли, коментарі та скорочує імена змінних. Webpack використовує TerserPlugin. Стискання (gzip/Brotli) на сервері зменшує розмір переданих даних.\\nДодаткові методи\\n\\n- Аналіз бандла за допомогою webpack-bundle-analyzer для виявлення великих залежностей.\\n- Заміна великих бібліотек (наприклад, moment.js на date-fns).\\n- Використання CDN для статичних ресурсів.\\n- Оптимізація зображень (стискання, lazy loading).\\nВисновок: Застосовуйте tree shaking і code splitting для сучасних застосунків, мініфікацію для продакшену, а аналіз бандла допоможе виявити вузькі місця. Це особливо корисно для великих проєктів із багатьма залежностями.","// utils.js\\nexport function used() { return 1; }\\nexport function unused() { return 2; }\\n// main.js\\nimport { used } from './utils';\\nconsole.log(used()); // unused() буде видалено\\n\\n// React lazy loading\\nconst LazyComponent = React.lazy(() => import('./LazyComponent'));\\n// Webpack dynamic import\\nbutton.addEventListener('click', () => {\\n  import('./module').then(module => module.default());\\n});"],[3153,"Розділення коду дозволяє розбити один великий застосунок на кілька частин, які завантажуються в міру потреби. У React це роблять за допомогою динамічних імпортів і React.lazy. Основний принцип — розділяти за маршрутами або великими компонентами, щоб користувач отримував лише потрібний код. Це пришвидшує початкове завантаження й заощаджує трафік.","Що таке розділення коду й для чого воно потрібне\\nКоли React-застосунок збирається в один чанк, увесь код — бібліотеки, компоненти, утиліти — потрапляє в один файл. Під час першого відвідування сайту браузер завантажує цей файл цілком, навіть якщо користувач бачить лише сторінку логіна. Це вповільнює завантаження й збільшує витрату трафіку. Розділення коду (code splitting) вирішує цю проблему: застосунок розбивається на кілька частин, які завантажуються лише тоді, коли вони справді потрібні.\\nЯк це працює в React\\nОсновний інструмент — динамічний імпорт. Замість статичного \`import Component from './Component'\` використовують \`const Component = React.lazy(() => import('./Component'))\`. React.lazy дозволяє відкласти завантаження компонента до моменту його рендерингу. Для обробки стану завантаження використовують компонент \`Suspense\`, який показує заглушку, поки чанк завантажується.\\n\\nПринципи розділення\\nРозділяти код потрібно за логічними межами застосунку. Найпоширеніший підхід — розділення за маршрутами: кожна сторінка стає окремим чанком. Також можна виділяти важкі бібліотеки (наприклад, графіки або редактори) в окремі чанки, щоб вони не гальмували початкове завантаження. Важливо не дробити код надто дрібно — кожен чанк має накладні витрати на HTTP-запит, тому оптимально, щоб розмір чанка був не менший за 10–20 КБ.\\nНалаштування у Webpack\\nWebpack автоматично створює окремі чанки для динамічних імпортів. Додатково можна налаштувати \`splitChunks\`, щоб винести спільні залежності (наприклад, React) в окремий vendor-чанк. Це дозволяє браузеру кешувати незмінні бібліотеки окремо від коду застосунку.\\n\\nВисновок\\nРозділення коду — це стандартна практика для великих React-застосунків. Воно пришвидшує перше завантаження, знижує навантаження на мережу й покращує користувацький досвід. Застосовуйте його завжди, коли застосунок містить кілька маршрутів або важкі компоненти, які не потрібні на старті.","import React, { Suspense, lazy } from 'react';\\nconst Dashboard = lazy(() => import('./Dashboard'));\\nconst Settings = lazy(() => import('./Settings'));\\n\\nfunction App() {\\n  return (\\n    <Suspense fallback={<div>Завантаження...</div>}>\\n      <Dashboard />\\n      <Settings />\\n    </Suspense>\\n  );\\n}\\n\\n// webpack.config.js\\nmodule.exports = {\\n  optimization: {\\n    splitChunks: {\\n      chunks: 'all',\\n      cacheGroups: {\\n        vendor: {\\n          test: /[\\\\\\\\/]node_modules[\\\\\\\\/]/,\\n          name: 'vendors',\\n          chunks: 'all',\\n        },\\n      },\\n    },\\n  },\\n};"],[3154,"Звичайно ні, якщо бібліотека не імпортується ніде в коді, вона не потрапляє в продакшн-білд. Сучасні збирачі (Webpack, Rollup, Vite) аналізують граф залежностей і виключають невикористовувані модулі. Проте це працює лише для ES-модулів (import/export), а не для CommonJS (require). Також важливо, щоб бібліотека була написана з підтримкою tree shaking.","Як збирачі обробляють невикористовувані бібліотеки\\nКоли ви збираєте проєкт для продакшену, збирач (наприклад, Webpack) будує граф залежностей, починаючи з точки входу. Якщо бібліотека ніде не імпортується, вона не потрапляє в цей граф і, відповідно, не включається в підсумковий бандл. Це називають виключенням мертвого коду (dead code elimination) і є частиною процесу tree shaking.\\nУмови для ефективного tree shaking\\n\\n- Використання ES-модулів (import/export) — вони статично аналізовані, на відміну від CommonJS (require), який динамічний.\\n- Бібліотека має бути написана з підтримкою tree shaking (часто вказують у package.json поле \`sideEffects: false\`).\\n- Збирач має бути налаштований на production-режим (наприклад, \`mode: 'production'\` у Webpack), який включає мініфікацію й видалення невикористовуваного коду.\\nПриклад\\n\\nЯкби ви написали \`import _ from 'lodash'\`, але не використали \`_\`, то залежно від налаштувань збирач міг би видалити імпорт, але якщо бібліотека використовує CommonJS, вона може потрапити в бандл цілком.\\nВинятки та нюанси\\nДеякі бібліотеки мають побічні ефекти під час імпорту (наприклад, поліфіли), тому їх не можна просто видалити. Для таких випадків у package.json указують \`sideEffects\` масивом файлів, які потрібно зберегти. Також, якщо бібліотека імпортується в якомусь модулі, але цей модуль сам не використовується, то бібліотеку може бути виключено лише якщо весь модуль видалено.\\nВисновок\\nУ більшості випадків невикористовувана бібліотека не потрапить у продакшн-білд, якщо ви використовуєте сучасний збирач і ES-модулі. Це допомагає зменшити розмір бандла й пришвидшити завантаження застосунку. Проте для надійності перевіряйте налаштування збирача й слідкуйте за тим, щоб бібліотеки були сумісні з tree shaking.","// main.js\\nimport { usedFunction } from './utils';\\n// Бібліотека lodash не імпортується, тому не потрапить у бандл\\nconsole.log(usedFunction());\\n\\n// utils.js\\nexport function usedFunction() { return 'ok'; }\\nexport function unusedFunction() { return 'no'; } // буде видалено під час tree shaking"],[3155,"Сучасні збирачі, такі як Vite і Rollup, відрізняються від Webpack швидкістю та простотою. Vite використовує нативні ES-модулі в dev-режимі та esbuild для швидкого збирання, а Rollup оптимізований для бібліотек. Webpack потужніший і гнучкіший, але складніший і повільніший. Переходити на Vite варто для нових проєктів і швидкої розробки, на Rollup — для публікації бібліотек, а Webpack залишити для складних легасі-проєктів з унікальними плагінами.","Вступ до проблеми вибору збирача\\nWebpack довгий час був стандартом де-факто для збирання фронтенд-застосунків. Проте його конфігурація часто громіздка, а швидкість роботи залишає бажати кращого, особливо на великих проєктах. Сучасні інструменти, такі як Vite і Rollup, пропонують інший підхід, заснований на використанні нативних можливостей браузера та ефективніших алгоритмів. Розуміння їхніх відмінностей допомагає розробникові усвідомлено вибирати інструмент під конкретне завдання, а не йти за звичкою.\\nКлючові відмінності Vite і Rollup від Webpack\\nГоловна відмінність Vite — у dev-режимі він не збирає весь проєкт заздалегідь. Замість цього він використовує нативні ES-модулі браузера, віддаючи вихідний код на запит. Це робить запуск сервера практично миттєвим, а гарячу заміну модулів — дуже швидкою. Для production-збирання Vite використовує Rollup, який відмінно оптимізує код. Rollup, у свою чергу, спеціалізується на tree-shaking і створенні чистих, компактних бандлів, що ідеально для бібліотек. Webpack же завжди виконує повне статичне збирання, що дає йому величезну гнучкість через плагіни та лоадери, але ціною складності та швидкості.\\nПрактичний приклад: конфігурація Vite\\n\\nЦей конфіг заміняє десятки рядків налаштування Webpack. Для порівняння, у Webpack знадобилося б налаштувати babel-loader, resolve.extensions, devServer і багато іншого. Vite бере на себе більшість рутинних завдань, дозволяючи розробникові зосередитися на коді.\\nКоли варто переходити на сучасні збирачі\\nПерехід на Vite виправданий для нових проєктів, де важлива швидкість розробки й простота конфігурації. Він відмінно підходить для SPA, SSR і навіть статичних сайтів. Rollup — найкращий вибір для публікації npm-бібліотек, оскільки він генерує чисті ESM і CJS бандли. Webpack залишається актуальним для складних корпоративних проєктів, де вже є безліч кастомних плагінів, або коли потрібне тонке налаштування кожного аспекту збирання, наприклад для мікрофронтендів.\\nВисновок\\nВибір збирача — це компроміс між швидкістю, простотою та гнучкістю. Для більшості нових проєктів Vite стане відмінним стартом, а Rollup — надійним інструментом для бібліотек. Webpack не застарів, але його варто застосовувати усвідомлено, коли його потуга справді необхідна. Розуміння цих нюансів дозволяє ухвалювати зважені архітектурні рішення.","// vite.config.js\\nimport { defineConfig } from 'vite';\\nimport react from '@vitejs/plugin-react';\\n\\nexport default defineConfig({\\n  plugins: [react()],\\n  server: {\\n    port: 3000,\\n  },\\n  build: {\\n    outDir: 'dist',\\n    sourcemap: true,\\n  },\\n});"],[3156,"Мікрофронтенди можуть підключатися двома основними способами: на етапі збирання (build-time) і під час виконання (runtime). За build-time хост імпортує віддалений модуль як звичайну залежність, і він потрапляє в бандл. За runtime хост завантажує віддалений код динамічно через Module Federation, script-теги або iframe. Вибір залежить від вимог до незалежності деплою та зв'язності команд.","Мікрофронтенди — це архітектурний підхід, за якого великий фронтенд-застосунок розбивається на кілька незалежно розроблюваних і деплоюваних частин. Ключове питання: як хост-застосунок (shell) дізнається про мікрофронтенди й включає їх у своє збирання або завантажує під час роботи.\\nОсновні способи підключення\\n\\n- Build-time інтеграція — мікрофронтенд публікують як npm-пакет, хост імпортує його як звичайний модуль. Усе потрапляє в один бандл.\\n- Runtime інтеграція через Module Federation — хост і віддалені модулі збираються окремо, а під час виконання обмінюються модулями через спільний контейнер.\\n- Динамічне завантаження скриптів — хост підвантажує JS-бандл мікрофронтенду через тег script і монтує його в DOM.\\n- Iframe — мікрофронтенд ізольований в окремому документі, спілкування через postMessage.\\nПриклад з Module Federation\\nУ конфігурації Webpack хост оголошує віддалені модулі, а мікрофронтенд — що він експортує.\\n\\nЯк це потрапляє у збирання\\nЗа build-time усе включається в один бандл на етапі компіляції. За runtime хост не містить коду мікрофронтенду — він лише посилається на remoteEntry.js, який завантажується в браузері. Це дозволяє деплоїти мікрофронтенди незалежно, без перезбирання хоста.\\nПідсумок: build-time простіший, але пов'язує релізи; runtime через Module Federation дає незалежність деплою й підходить для великих команд, тоді як iframe і script-теги застосовують для ізоляції або legacy-систем.","// webpack.config.js хоста\\nnew ModuleFederationPlugin({\\n  remotes: {\\n    products: 'products@http://localhost:3001/remoteEntry.js'\\n  }\\n});\\n\\n// webpack.config.js мікрофронтенда\\nnew ModuleFederationPlugin({\\n  name: 'products',\\n  filename: 'remoteEntry.js',\\n  exposes: {\\n    './ProductList': './src/ProductList'\\n  }\\n});\\n\\n// Використання в хості\\nconst ProductList = React.lazy(() => import('products/ProductList'));"],[3157,"Мікрофронтенди потрібні, коли над одним великим застосунком працює багато команд, і вони заважають одна одній під час релізів. Розділення допомагає кожній команді деплоїти свою частину незалежно. Критерії: розмір команди, частота релізів, різні технології, ізоляція доменів. Але якщо застосунок невеликий, мікрофронтенди додадуть зайвої складності.","Мікрофронтенди — це архітектурний підхід, за якого єдиний фронтенд-застосунок розбивається на кілька незалежно розроблюваних і деплоюваних частин. Кожна частина відповідає за свій бізнес-домен і може використовувати власний стек, мати свій цикл релізів і свою команду.\\nПричини переходу\\n\\n- Зростання команди: коли над одним SPA працює 20+ розробників, релізи стають вузьким місцем.\\n- Незалежний деплой: одна команда може викотити фічу, не чекаючи на решту.\\n- Різні технології: старий Angular-модуль і новий React-модуль можуть співіснувати.\\n- Ізоляція збоїв: падіння одного мікрофронтенду не обов'язково ламає весь застосунок.\\nКритерії для розділення\\n\\n- Є чіткі бізнес-домени (каталог, кошик, профіль).\\n- Команди автономні й володіють своїми доменами end-to-end.\\n- Потрібен незалежний релізний цикл.\\n- Застосунок уже великий і монолітний фронтенд гальмує розробку.\\nПриклад з Module Federation\\n\\nТут хост-застосунок підвантажує віддалений модуль каталогу під час виконання, а спільні залежності (React) шаряться, щоб не дублювати їх.\\nКоли не варто\\nЯкщо застосунок невеликий, команда одна й релізи не конфліктують, мікрофронтенди принесуть більше проблем: ускладниться збирання, виросте розмір бандла, з'являться проблеми зі спільним станом і стилями.\\nПідсумок: застосовувати мікрофронтенди варто під час масштабування команд і потреби в незалежних релізах за бізнес-доменами; у невеликих проєктах це надлишково.","// host/webpack.config.js\\nnew ModuleFederationPlugin({\\n  name: 'host',\\n  remotes: {\\n    catalog: 'catalog@https://cdn.example.com/remoteEntry.js'\\n  },\\n  shared: ['react', 'react-dom']\\n});\\n\\n// У коді хоста\\nconst Catalog = React.lazy(() => import('catalog/App'));"],[3158,"HTTPS (HyperText Transfer Protocol Secure) — це захищена версія протоколу HTTP, яка використовує SSL/TLS для шифрування даних. Він працює через порт 443 і захищає передані дані від перехоплення або зміни.","Протокол HTTPS — це розширення протоколу HTTP, що забезпечує безпечне з'єднання між клієнтом (наприклад, браузером) і сервером. Він використовує:\\nSSL/TLS:\\n\\n- Шифрує передані дані, щоб їх не можна було перехопити.\\n\\n- Забезпечує аутентифікацію сервера через сертифікати.\\n\\nПорт 443:\\n\\n- Це стандартний порт для HTTPS.\\n\\nПриклад роботи HTTPS:\\n\\n- Користувач заходить на захищений сайт (наприклад, https://example.com).\\n\\n- Браузер запитує в сервера сертифікат.\\n\\n- Сервер надсилає сертифікат, що підтверджує його справжність.\\n\\n- Установлюється зашифроване з'єднання.\\n\\nHTTPS необхідний для захисту даних, особливо на сайтах, де вводять конфіденційні дані (паролі, номери карт).",null],[3159,"Прикладний рівень надає такі служби, як електронна пошта (SMTP), передавання файлів (FTP), керування доступом (SSH) і мережевий віртуальний термінал (Telnet).","Прикладний рівень — це верхній рівень мережевої моделі, який забезпечує інтерфейс між користувачем і мережею. Основні служби, що надаються:\\n\\n- Поштові служби (Mail services):\\nПриклад: SMTP для надсилання листів, POP3/IMAP для їхнього отримання.\\n\\n- Передавання файлів (File transfer):\\nПриклад: FTP для завантаження/вивантаження файлів.\\n\\n- Керування доступом (Access management):\\nПриклад: SSH для безпечного підключення до віддалених серверів.\\n\\n- Мережевий віртуальний термінал (Network virtual terminal):\\nПриклад: Telnet, який дозволяє керувати віддаленим пристроєм.\\n\\n- Служби каталогів (Directory services):\\nПриклад: LDAP для пошуку інформації про користувачів і пристрої.\\n\\nПрикладний рівень відіграє ключову роль у забезпеченні взаємодії користувача з мережею через різні застосунки.",null],[3160,"Заголовки додаються на рівнях 6 (представлення), 5 (сеансів), 4 (транспортному) і 3 (мережевому). Трейлер додається на канальному рівні (рівень 2).","У моделі OSI дані інкапсулюються на кожному рівні, додаючи заголовки та, іноді, трейлери:\\n\\n- Рівень 6 (представлення): Додає заголовок, пов'язаний із форматом даних (наприклад, кодування).\\n\\n- Рівень 5 (сеансів): Додає заголовок для керування сеансом зв'язку (наприклад, ідентифікатори сеансу).\\n\\n- Рівень 4 (транспортний): Додає заголовок з інформацією про номери портів і сегментацію.\\n\\n- Рівень 3 (мережевий): Додає заголовок з IP-адресами відправника та отримувача.\\n\\n- Канальний рівень (рівень 2): Додає заголовок для адресації на рівні MAC і трейлер для перевірки цілісності даних (CRC).\\n\\nДодавання заголовків і трейлерів дозволяє кожному рівню обробляти дані коректно й передавати їх між вузлами.",null],[3161,"Коли пакет даних переміщується від нижнього до верхнього рівня моделі OSI, заголовки, додані раніше, видаляються, і залишаються лише вихідні дані.","Процес деінкапсуляції включає:\\n\\n- Канальний рівень (рівень 2): Видаляє трейлер і заголовок, залишаючи кадр.\\n\\n- Мережевий рівень (рівень 3): Видаляє мережевий заголовок, залишаючи сегмент або повідомлення.\\n\\n- Транспортний рівень (рівень 4): Прибирає інформацію про порти, залишаючи дані для сеансового рівня.\\n\\n- Представницький і сеансовий рівні (рівні 5–6): Прибирають службові дані, залишаючи вихідний контент, готовий для передавання застосунку.\\n\\nВидалення заголовків дозволяє відновити вихідні дані, надіслані відправником.",null],[3162,"Коли пакет даних переміщується від верхнього до нижнього рівня моделі OSI, на кожному рівні додаються заголовки. Ці заголовки містять інформацію, необхідну для передавання даних між пристроями.","Процес інкапсуляції включає:\\n\\n- Представницький і сеансовий рівні (рівні 6–5): Додають заголовки для кодування та керування сеансом.\\n\\n- Транспортний рівень (рівень 4): Додає інформацію про сегментацію даних і номери портів (TCP/UDP).\\n\\n- Мережевий рівень (рівень 3): Додає IP-заголовок з адресами відправника та отримувача.\\n\\n- Канальний рівень (рівень 2): Додає MAC-адреси й трейлер для перевірки помилок.\\n\\n- Фізичний рівень (рівень 1): Перетворює дані на електричні сигнали або радіохвилі для передавання.\\n\\nІнкапсуляція даних дозволяє кожному рівню моделі OSI підготувати інформацію для успішного передавання по мережі.",null],[3163,"Зональний файрвол — це вдосконалений метод міжмережевого екрана зі збереженням стану (stateful firewall). Він організовує трафік між довіреними та недовіреними зонами, спираючись на правила безпеки, які застосовують до трафіку між зонами.","Принципи роботи зонального файрвола:\\n1. Визначення зон: Кожному інтерфейсу пристрою (наприклад, маршрутизатора) призначається певна зона, така як «внутрішня мережа» (trusted) або «зовнішня мережа» (untrusted).\\n2. Застосування правил: Трафік між зонами дозволяється або блокується на основі попередньо визначених політик безпеки. Наприклад:\\n\\n- Заборонити доступ із «зовнішньої мережі» у «внутрішню мережу».\\n\\n- Дозволити доступ до певних служб, таких як вебсервер або поштовий сервер.\\n\\n3. Збереження стану: Зональний файрвол зберігає інформацію про поточні з'єднання у stateful таблиці, що дозволяє пропускати лише дозволені відповіді.\\nСпособи реалізації:\\n\\n- CBAC (Context-Based Access Control): Традиційний метод створення ACL (списків контролю доступу) для керування трафіком.\\n\\n- Zone-Based Firewall: Сучасніший підхід, заснований на керуванні трафіком між зонами.\\n\\nПереваги:\\n\\n- Підвищена безпека завдяки чіткому розділенню зон.\\n\\n- Зручність керування правилами безпеки.\\n\\nЗональні файрволи підходять для керування складними мережами, де потрібне чітке розділення довірених і недовірених сегментів.",null],[3164,"Серверна ферма — це група серверів, об'єднаних для виконання завдань із високою продуктивністю. Їх використовують для хостингу вебсайтів, хмарних сервісів і складних обчислень.","Основні характеристики серверної ферми:\\n\\n- Об'єднання серверів: Сервери об'єднані в одну інфраструктуру для спільної роботи.\\n\\n- Розподіл навантаження: Використовується балансування навантаження для рівномірного розподілу запитів між серверами.\\n\\n- Підвищення продуктивності: Дозволяє обробляти безліч запитів одночасно, збільшуючи швидкість та ефективність.\\n\\n- Застосування:\\n\\n- Хостинг вебсайтів.\\n\\n- Обробка великих даних.\\n\\n- Проведення складних обчислень, наприклад у наукових дослідженнях.\\n\\nПриклад роботи:\\nСерверна ферма, яку використовують для хостингу, розподіляє запити користувачів через балансувальник навантаження, який перенаправляє трафік на доступні сервери.\\nСерверні ферми забезпечують високу продуктивність і відмовостійкість, що робить їх ключовим компонентом сучасних центрів обробки даних.",null],[3165,"Три методи аутентифікації — це біометрія (наприклад, відбиток пальця), токен (електронний пристрій або карта) і пароль. Для підвищення безпеки можна використовувати двофакторну аутентифікацію, комбінуючи два з цих методів.","Основні методи аутентифікації:\\n1. Паролі:\\n\\n- Простий і поширений засіб захисту.\\n\\n- Уразливий до підбору або злому, якщо паролі слабкі.\\n\\n2. Біометрія:\\n\\n- Використання унікальних характеристик людини, таких як відбитки пальців, сканування райдужки або розпізнавання обличчя.\\n\\n- Високий рівень захисту, але потребує спеціального обладнання.\\n\\n3. Токени:\\n\\n- Фізичні пристрої, такі як смарт-карти або USB-ключі, які генерують одноразові коди.\\n\\n- Надійні, але можуть бути втрачені.\\n\\nДвофакторна аутентифікація (2FA):\\nКомбінація двох методів (наприклад, пароля й токена) значно підвищує безпеку, знижуючи ймовірність несанкціонованого доступу.\\nПриклад: Для входу в банківський акаунт користувач уводить пароль (1-й фактор) і підтверджує вхід через SMS-код (2-й фактор).\\nВикористання кількох рівнів аутентифікації допомагає захистити системи й дані від несанкціонованого доступу.",null],[3166,"CIA-тріада — це основа інформаційної безпеки:\\n\\n- Конфіденційність (Confidentiality): Дані захищені від несанкціонованого доступу.\\n\\n- Цілісність (Integrity): Дані точні й не змінені без дозволу.\\n\\n- Доступність (Availability): Дані й системи доступні, коли вони потрібні.","1. Конфіденційність:\\n\\n- Забезпечує захист даних від несанкціонованого доступу.\\n\\n- Методи: шифрування, контроль доступу, паролі.\\n\\n- Приклад: ваш пароль не має бути відомий іншим особам.\\n\\n2. Цілісність:\\n\\n- Гарантує, що дані залишаються точними й повними.\\n\\n- Зміни можуть робити лише авторизовані користувачі.\\n\\n- Приклад: після звільнення співробітника дані про нього оновлюють лише певні спеціалісти.\\n\\n3. Доступність:\\n\\n- Дані й системи мають бути доступні авторизованим користувачам у потрібний час.\\n\\n- Загрози: атаки типу DoS, збої обладнання.\\n\\n- Приклад: система має працювати, щоб співробітники могли перевіряти інформацію про свої завдання.\\n\\nCIA-тріада допомагає розробляти надійні та безпечні системи, мінімізуючи ризики для даних.",null],[3167,"VPN (Virtual Private Network) створює захищене з'єднання через публічні мережі, такі як Інтернет. Воно дозволяє користувачам підключатися до приватної мережі віддалено, забезпечуючи шифрування даних.","1. Що таке VPN:\\n\\n- Це технологія для створення віртуального захищеного каналу зв'язку через небезпечну мережу (наприклад, Інтернет).\\n\\n- Дані шифруються, що запобігає перехопленню інформації зловмисниками.\\n\\n2. Застосування:\\n\\n- Захист конфіденційної інформації у загальнодоступних мережах.\\n\\n- Віддалена робота: співробітники можуть підключатися до корпоративної мережі, перебуваючи в іншому місці.\\n\\n- Обхід географічних обмежень (наприклад, доступ до заблокованих сайтів).\\n\\n3. Як працює:\\n\\n- Використовує тунелювання (tunneling protocols) для захисту даних.\\n\\n- Приклади протоколів: OpenVPN, PPTP, L2TP.\\n\\nVPN широко використовують для захисту даних і забезпечення віддаленого доступу, особливо в корпоративному середовищі.",null],[3168,"Симетричне шифрування: Використовується один ключ для шифрування та дешифрування. Це швидко, але потребує безпечного передавання ключа.\\nАсиметричне шифрування: Використовує пару ключів (відкритий і закритий). Це безпечніше, але повільніше.","1. Симетричне шифрування:\\n\\n- Той самий ключ використовується для шифрування та дешифрування.\\n\\n- Переваги: висока швидкість роботи.\\n\\n- Недоліки: потрібно безпечно передати ключ.\\n\\n- Приклад: алгоритми AES, DES.\\n\\n2. Асиметричне шифрування:\\n\\n- Використовуються два ключі: відкритий (для шифрування) і закритий (для дешифрування).\\n\\n- Переваги: безпечне передавання даних.\\n\\n- Недоліки: низька швидкість.\\n\\n- Приклад: RSA.\\n\\nВисновок: Симетричне шифрування підходить для великих обсягів даних, а асиметричне — для безпечного передавання ключів.","from cryptography.fernet import Fernet\\nkey = Fernet.generate_key()\\ncipher = Fernet(key)\\nencrypted = cipher.encrypt(b\\"Confidential Data\\")\\ndecrypted = cipher.decrypt(encrypted)\\n\\nfrom cryptography.hazmat.primitives.asymmetric import rsa\\nfrom cryptography.hazmat.primitives.asymmetric import padding\\nprivate_key = rsa.generate_private_key(public_exponent=65537, key_size=2048)\\npublic_key = private_key.public_key()\\nencrypted = public_key.encrypt(b\\"Confidential Data\\", padding.OAEP(\\n      padding.MGF1(algorithm=hashes.SHA256()), hashes.SHA256(), None))"],[3169,"IPsec працює на 3-му рівні моделі OSI (мережевому рівні). Він забезпечує захист даних на рівні IP-пакетів з використанням методів шифрування та аутентифікації.","1. Що таке IPsec?\\n\\n- IPsec (Internet Protocol Security) — це набір протоколів для забезпечення безпечного передавання даних по IP-мережах.\\n\\n- Використовують для шифрування, перевірки цілісності даних та аутентифікації джерела.\\n\\n2. На якому рівні працює:\\nIPsec функціонує на мережевому рівні (Layer 3) моделі OSI. Це дозволяє йому захищати IP-пакети й взаємодіяти з різними мережами.\\n3. Переваги:\\n\\n- Забезпечує безпеку для всіх застосунків, які використовують IP.\\n\\n- Підходить для створення VPN-з'єднань.\\n\\nIPsec — це стандарт безпеки на мережевому рівні, який широко використовують для забезпечення захищеної взаємодії між мережами.",null],[3170,"Режим тунелю — це спосіб передавання даних, за якого пристрої не використовують IPsec напряму. Замість цього створюється віртуальний тунель через шлюзи, який забезпечує шифрування всього трафіку між вузлами.","1. Що таке режим тунелю?\\n\\n- Тунельний режим використовують для захисту даних між двома мережами через спільний канал.\\n\\n- Усі дані, включно з оригінальними IP-заголовками, шифруються й поміщаються в нові IP-пакети.\\n\\n2. Застосування:\\n\\n- Використовують для шифрування трафіку між безпечними шлюзами.\\n\\n- Приклад: з'єднання між корпоративним маршрутизатором Cisco і PIX Firewall.\\n\\n3. Переваги:\\n\\n- Забезпечує безпеку даних під час передавання через небезпечні мережі.\\n\\n- Зручний для організації VPN між кількома мережами.\\n\\nРежим тунелю корисний, коли потрібно захистити дані між двома точками, забезпечивши їхнє повне шифрування.",null],[3171,"Цифровий підпис — це математичний метод перевірки справжності та цілісності електронних повідомлень, документів або програмного забезпечення. Його використовують для запобігання підробленню даних і підтвердження їхнього джерела.","1. Що таке цифровий підпис?\\n\\n- Це електронний еквівалент рукописного підпису, який забезпечує справжність даних.\\n\\n- Працює на основі криптографії з відкритим і закритим ключем.\\n\\n2. Як працює:\\n\\n- Відправник використовує закритий ключ для створення підпису (хешування даних).\\n\\n- Отримувач використовує відкритий ключ для перевірки підпису.\\n\\n- Якщо дані було змінено, підпис стає недійсним.\\n\\n3. Застосування:\\n\\n- Підтвердження відправника (аутентифікація).\\n\\n- Захист даних від зміни (цілісність).\\n\\n- Приклад: підписані електронні документи або захищені транзакції.\\n\\nПриклад коду (Python):\\n\\nЦифрові підписи — це надійний спосіб перевірки справжності та захисту даних у цифровому світі.","from cryptography.hazmat.primitives import hashes\\nfrom cryptography.hazmat.primitives.asymmetric import padding, rsa\\n\\n# Генерація ключів\\nprivate_key = rsa.generate_private_key(public_exponent=65537, key_size=2048)\\npublic_key = private_key.public_key()\\n\\n# Створення підпису\\nmessage = b\\"Secure Message\\"\\nsignature = private_key.sign(message, padding.PSS(mgf=padding.MGF1(hashes.SHA256()), salt_length=padding.PSS.MAX_LENGTH), hashes.SHA256())\\n\\n# Перевірка підпису\\ntry:\\n      public_key.verify(signature, message, padding.PSS(mgf=padding.MGF1(hashes.SHA256()), salt_length=padding.PSS.MAX_LENGTH), hashes.SHA256())\\n      print(\\"Підпис валідний\\")\\nexcept Exception:\\n      print(\\"Підпис недійсний\\")"],[3172,"Авторизація — це процес, який визначає, які ресурси та дії доступні користувачеві після успішної аутентифікації. Її використовують для застосування політик безпеки, щоб обмежити доступ до мережевих ресурсів на основі прав користувача.","1. Що таке авторизація?\\n\\n- Авторизація відбувається після аутентифікації, коли користувач уже довів свою особу.\\n\\n- Вона вирішує, які ресурси може використовувати користувач і які операції йому дозволено виконувати.\\n\\n2. Застосування:\\n\\n- У компанії це може бути доступ до файлів, баз даних або системи керування.\\n\\n- Наприклад, лише адміністратор може змінювати налаштування системи, тоді як звичайний користувач може лише переглядати дані.\\n\\n3. Процес:\\n\\n- Після того як аутентифікація пройшла успішно, система перевіряє, які права доступу має користувач на основі його ролі (наприклад, адміністратор, менеджер, співробітник).\\n\\n- Приклад: Користувач, який пройшов аутентифікацію через VPN, може мати доступ до певних серверів або застосунків, залежно від його ролі.\\n\\nАвторизація необхідна для реалізації політики безпеки й розмежування доступу до мережевих ресурсів на основі ролей користувачів.",null],[3173,"IPS (Intrusion Prevention System) — це система для виявлення та запобігання атакам, яка аналізує трафік на наявність шкідливої активності й робить кроки для її блокування. Файрвол, з іншого боку, фільтрує трафік на основі заздалегідь визначених правил, контролюючи, які з'єднання дозволені, а які — заблоковані.","1. Функції IPS:\\n\\n- IPS аналізує мережевий трафік, виявляє шкідливі дії й намагається їм запобігти.\\n\\n- Він може блокувати атаку в реальному часі або змінити безпеку мережі, щоб запобігти її успіху.\\n\\n2. Функції файрвола:\\n\\n- Файрвол — це пристрій, який фільтрує трафік, дозволяючи або забороняючи його залежно від налаштованих правил.\\n\\n- Він може блокувати доступ за IP-адресами, портами або протоколами.\\n\\n3. Основні відмінності:\\n\\n- IPS активно реагує на загрози й намагається їх блокувати, тоді як файрвол лише фільтрує трафік за заздалегідь установленими правилами.\\n\\n- Файрвол може бути частиною системи IPS, але IPS також використовує складніші методи для запобігання атакам, такі як аналіз поведінки трафіку.\\n\\nПриклад:\\nЯкщо IPS виявляє спробу SQL-ін'єкції в запиті, він може її заблокувати, тоді як файрвол просто може не дозволити трафіку з невідомої IP-адреси пройти.\\nIPS є активнішою системою безпеки, спрямованою на запобігання атакам у реальному часі, тоді як файрвол виконує простіше завдання — блокувати небажані з'єднання.",null],[3174,"IP Spoofing — це техніка, за якої зловмисник підміняє свою IP-адресу, щоб приховати справжнє джерело трафіку. Це використовують для маскування атак, таких як DDoS, або для обходу заходів безпеки.","1. Що таке IP Spoofing?\\n\\n- IP Spoofing дозволяє зловмисникові підмінити IP-адресу, щоб трафік здавався таким, що виходить від іншого пристрою.\\n\\n- Цю техніку використовують для приховування реального джерела атаки або для обходу фільтрації на рівні мережі.\\n\\n2. Як це працює?\\n\\n- Зловмисник надсилає пакети з підробленими заголовками IP, що робить неможливим відстеження реального джерела трафіку.\\n\\n- Цю техніку часто використовують під час проведення атак типу Denial of Service (DoS), коли атакувальник хоче приховати свою справжню IP-адресу.\\n\\n3. Застосування в атаці:\\n\\n- Наприклад, в атаці DDoS зловмисник може надіслати запити з підробленими IP-адресами, роблячи важко виявним реального ініціатора атаки.\\n\\nIP Spoofing — це небезпечна техніка, яка використовує підміну IP-адрес для приховування джерела трафіку й проведення атак. Захист від таких атак потребує уважного налаштування фільтрації та моніторингу мережевого трафіку.",null],[3175,"Загроза — це щось, що може використати уразливість для руйнування або пошкодження активу (наприклад, даних).\\nУразливість — це слабке місце в захисті, яке може бути використане загрозою.\\nРизик — це поєднання активу, загрози та уразливості. Це ймовірність того, що загроза використає уразливість для завдання шкоди активу.","1. Загроза:\\n\\n- Загроза може бути як навмисною (наприклад, хакерська атака), так і випадковою (наприклад, втрата даних через збій обладнання).\\n\\n- Приклад: Хакер, який використовує уразливість у системі, щоб украсти конфіденційну інформацію.\\n\\n2. Уразливість:\\n\\n- Уразливість — це слабкість або помилка в захисті, яка може бути використана загрозою для завдання шкоди.\\n\\n- Приклад: Застаріле програмне забезпечення, яке має відомі уразливості.\\n\\n3. Ризик:\\n\\n- Ризик — це ймовірність того, що загроза використає уразливість для завдання шкоди активу. Це також включає в себе можливі наслідки для активу.\\n\\n- Формула:\\nЗагроза (T) + Уразливість (V) = Ризик (R)\\n\\n- Приклад: Якщо у вас є конфіденційна інформація (актив), а ваша система має уразливість (наприклад, слабкі паролі), то ризик буде високим, якщо загроза (хакер) використає цю уразливість для доступу до інформації.\\n\\nРозуміння загроз, уразливостей і ризиків допомагає організаціям ефективно керувати безпекою й мінімізувати потенційні втрати.",null],[3176,"DNS (Domain Name Server) — це система, яка перекладає доменні імена в IP-адреси, необхідні для підключення до ресурсів в інтернеті. Це дозволяє користувачеві використовувати легко запам'ятовувані адреси замість числових IP-адрес.","1. Основна роль DNS:\\n\\n- DNS допомагає пристроям знайти потрібні ресурси в інтернеті, перетворюючи доменні імена в IP-адреси.\\n\\n- Наприклад, якщо ви вводите в браузері адресу «example.com», DNS-сервер перетворює її на IP-адресу, наприклад 192.0.2.1, щоб пристрій міг установити з'єднання із сервером.\\n\\n2. Як працює DNS:\\n\\n- Коли ви вводите адресу в браузері, запит надсилається на DNS-сервер, який шукає відповідну IP-адресу.\\n\\n- Якщо сервер не має запису, він запитує інформацію в інших DNS-серверів доти, доки не отримає потрібний IP.\\n\\n3. Роль DNS-серверів:\\n\\n- В інтернеті існує безліч DNS-серверів, які містять записи про доменні імена та їхні IP-адреси.\\n\\n- Система DNS є розподіленою й працює за принципом ієрархії: від кореневих серверів до серверів, що відповідають за конкретні домени.\\n\\nDNS-сервери є важливою частиною інфраструктури інтернету, забезпечуючи можливість використання зручних доменних імен замість числових адрес для зв'язку з ресурсами в мережі.",null],[3177,"DNS використовує протоколи TCP і UDP. Порт для DNS-запитів — 53.","1. Протоколи для DNS:\\n\\n- DNS використовує як TCP, так і UDP.\\n\\n- UDP використовують для більшості DNS-запитів, оскільки цей протокол швидший і ефективніший для невеликих пакетів даних.\\n\\n- TCP використовують для передавання більших даних, наприклад під час передавання зонних файлів.\\n\\n2. Порт DNS:\\n\\n- Стандартний порт для DNS-запитів — 53.\\n\\n- Цей порт використовують як для TCP, так і для UDP з'єднань.\\n\\n3. Застосування:\\n\\n- Коли ви запитуєте домен, наприклад «www.example.com», запит передається на DNS-сервер через порт 53 за протоколом UDP, якщо відповідь невелика.\\n\\n- У разі складніших запитів або великих відповідей може використовуватися TCP.\\n\\nРозуміння протоколів і портів DNS важливе для налаштування та усунення неполадок у мережі, а також для забезпечення безпеки DNS-серверів.",null],[3178,"Засоби передавання даних (наприклад, кабелі) працюють на фізичному рівні (Layer 1) моделі OSI. Цей рівень відповідає за передавання необроблених даних фізичними каналами, наприклад через кабелі або радіохвилі.","1. Фізичний рівень:\\n\\n- Фізичний рівень (Layer 1) моделі OSI відповідає за фізичне передавання даних по мережі.\\n\\n- Він визначає електричні, механічні та процедурні характеристики для активації, передавання та приймання необроблених бітів через фізичний канал.\\n\\n- На цьому рівні перебувають такі компоненти, як кабелі, з'єднувачі, радіохвилі та оптоволокно.\\n\\n2. Роль засобів передавання даних:\\n\\n- Засоби передавання даних — це фізична інфраструктура, через яку передаються дані.\\n\\n- Наприклад, це можуть бути виті пари, оптоволоконні кабелі або радіохвилі. Ці засоби забезпечують «перенесення» даних, але вони не обробляють даних.\\n\\n3. Приклад застосування:\\n\\n- Коли ви передаєте дані по мережі, наприклад через Ethernet, фізичний рівень відповідає за перетворення даних на сигнали, які можуть бути надіслані через кабель або радіоефір.\\n\\nРозуміння того, що засоби передавання належать до фізичного рівня, допомагає в правильному налаштуванні й обслуговуванні мережі, а також у діагностиці проблем із підключенням.",null],[3179,"Контрольна сума не може виявити багатобітових помилок, коли кілька бітів даних змінюються одночасно, особливо якщо вони компенсують один одного.","1. Контрольна сума:\\n\\n- Контрольна сума — це метод перевірки цілісності даних, який використовують для виявлення помилок під час передавання або зберігання даних.\\n\\n- Її обчислюють шляхом додавання всіх бітів або байтів у повідомленні, а потім обчислюють залишок від ділення на задане число (звичайно на 255 або 65535).\\n\\n2. Багатобітові помилки:\\n\\n- Багатобітові помилки, коли кілька бітів даних змінюються одночасно, не завжди можуть бути виявлені за допомогою контрольної суми.\\n\\n- Приклад: якщо два біти змінилися і їхні зміни компенсують один одного (наприклад, один біт змінився на 1, а інший на 0), то контрольна сума не виявить цієї помилки.\\n\\n3. Застосування:\\nКонтрольні суми звичайно використовують у протоколах, таких як UDP і TCP, але вони не гарантують повного виявлення помилок, особливо для складніших помилок. Для надійнішої перевірки цілісності даних часто використовують складніші методи, такі як циклічні надлишкові коди (CRC).\\nХоча контрольна сума ефективна для виявлення деяких типів помилок, вона не є ідеальною для виявлення всіх видів помилок, і в разі критичних застосунків слід використовувати складніші методи перевірки.",null],[3180,"Зворотний проксі-сервер приймає запити від клієнтів і перенаправляє їх на відповідні вебсервери, приховуючи їх від кінцевого користувача. Він також може використовуватися для захисту конфіденційних даних на серверах.","1. Функції зворотного проксі:\\nПеренаправлення запитів: Зворотний проксі приймає запити від клієнтів (наприклад, веббраузерів) і перенаправляє їх на внутрішні вебсервери. Це дозволяє приховати від клієнтів інформацію про внутрішні сервери та їхню архітектуру.\\nБалансування навантаження: Зворотний проксі може також служити для балансування навантаження, розподіляючи запити між кількома вебсерверами, щоб запобігти перевантаженню окремих серверів.\\nКешування: Зворотні проксі можуть кешувати ресурси, які часто запитують, щоб пришвидшити обробку запитів і знизити навантаження на сервери.\\n2. Використання в безпеці:\\nЗахист конфіденційних даних: Зворотний проксі обмежує прямий доступ до внутрішніх серверів і захищає їх від можливих загроз. Він може фільтрувати запити й блокувати потенційно небезпечний трафік, підвищуючи рівень безпеки.\\nSSL-термінація: Зворотний проксі може використовуватися для завершення SSL-з'єднань, дешифруючи трафік перед передаванням його на вебсервери, що пришвидшує обробку запитів.",null],[3181,"Щоб отримати IP-адресу доменного імені, можна використати команду ping або nslookup у командному рядку чи терміналі.","1. Використання команди PING:\\n\\n- Команда ping надсилає пакети на домен і отримує його IP-адресу у відповіді. Приклад:\\n\\n- Ця команда дозволяє дізнатися, яка IP-адреса відповідає доменному імені в мережі.\\n\\n2. Використання команди nslookup:\\n\\n- Команда nslookup надає детальнішу інформацію про DNS-записи домену, включно з його IP-адресами. Приклад:\\n\\n- Це дозволяє отримати інформацію про домени та їхні пов'язані IP-адреси, а також інші записи DNS, такі як MX-записи (для пошти).\\n\\nЩоб отримати IP-адресу домену, можна використати команди ping або nslookup, які виконують запити DNS і виводять відповідну IP-адресу.","ping example.com\\n\\nnslookup example.com"],[3182,"У TCP керування потоком здійснюється за допомогою протоколу ковзного вікна, де приймальна сторона вказує розмір вікна, який показує кількість байтів, які вона може прийняти.","1. Протокол ковзного вікна:\\n\\n- У TCP керування потоком здійснюється за допомогою протоколу ковзного вікна. Це дозволяє контролювати обсяг даних, який відправник може передати до отримання підтвердження від отримувача.\\n\\n- Приймач оголошує розмір вікна, який показує, скільки байтів він може прийняти без перевантаження свого буфера. Відправник не може передавати даних більше, ніж указано у вікні.\\n\\n2. Роль керування потоком у TCP:\\n\\n- Цей механізм запобігає перевантаженню приймального пристрою, знижуючи ймовірність втрати даних.\\n\\n- Приймач може регулювати розмір вікна залежно від своєї здатності приймати дані.\\n\\n3. Приклад:\\nЯкщо вікно розміром 10 КБ, відправник може надіслати не більше 10 КБ даних, перш ніж має отримати підтвердження від приймача. Коли приймач готовий прийняти більше даних, він може збільшити розмір вікна.\\nTCP використовує механізм ковзного вікна для ефективного керування потоком даних, що дозволяє підтримувати баланс між продуктивністю й надійністю передавання.",null],[3183,"FTP (File Transfer Protocol) — це мережевий протокол, який використовують для передавання файлів між пристроями через Інтернет з використанням моделі клієнт-сервер. Незважаючи на те, що його заміняють безпечнішими протоколами, такими як SFTP і SCP, FTP досі широко використовують.","1. FTP (File Transfer Protocol):\\n\\n- FTP дозволяє користувачам передавати файли між клієнтом і сервером через мережу. Це один із найстаріших протоколів для обміну файлами й працює за моделлю клієнт-сервер.\\n\\n- Протокол FTP може працювати як в активному, так і в пасивному режимі. В активному режимі клієнт ініціює з'єднання із сервером, а в пасивному сервер слухає на певному порту й очікує з'єднання від клієнта.\\n\\n2. Обмеження FTP:\\n\\n- Незважаючи на його широке використання, FTP не забезпечує шифрування даних, що робить його уразливим для атак. Через це його починають заміняти безпечнішими протоколами, такими як SFTP (Secure File Transfer Protocol) і SCP (Secure Copy Protocol).\\n\\n- SFTP і SCP використовують SSH для захисту переданих даних, забезпечуючи безпеку й конфіденційність.\\n\\nFTP — це стандартний протокол для передавання файлів, але з огляду на його недоліки щодо безпеки його поступово заміняють захищенішими альтернативами, такими як SFTP і SCP.",null],[3184,"Існує чотири типи IP-адрес: публічні IP-адреси, приватні IP-адреси, статичні IP-адреси та динамічні IP-адреси. Вони різняться за своєю функцією та поведінкою.","1. Публічні IP-адреси:\\nПублічні IP-адреси використовують для зв'язку пристроїв в Інтернеті. Ці адреси унікальні й призначаються Інтернет-провайдером. Публічна IP-адреса дозволяє пристроям взаємодіяти з іншими пристроями в глобальній мережі.\\n2. Приватні IP-адреси:\\nПриватні IP-адреси використовують для мереж, не підключених напряму до Інтернету, наприклад у локальних мережах (LAN). Ці адреси не можуть бути використані в Інтернеті й звичайно призначаються пристроям усередині організації.\\n3. Статичні IP-адреси:\\nСтатичні IP-адреси — це IP-адреси, які призначають пристроям на постійній основі. Вони не змінюються з часом і підходять для серверів і пристроїв, що потребують постійного підключення.\\n4. Динамічні IP-адреси:\\nДинамічні IP-адреси призначаються автоматично через DHCP (Dynamic Host Configuration Protocol). Ці адреси можуть змінюватися за кожного підключення пристрою до мережі, що дозволяє заощаджувати адресний простір і спрощує налаштування мережі.",null],[3185,"- 400-ті помилки (наприклад, \`400 Bad Request\`, \`404 Not Found\`) означають, що проблема на стороні клієнта (неправильний запит, відсутність сторінки тощо).\\n\\n- 500-ті помилки (наприклад, \`500 Internal Server Error\`, \`502 Bad Gateway\`) означають, що сервер не зміг обробити коректний запит через свою помилку.","HTTP-статуси діляться на класи:\\n\\n- 4xx (Клієнтські помилки) — запит містить помилку або не може бути виконаний.\\n\\n- \`400 Bad Request\` — сервер не зрозумів запиту (наприклад, невірний синтаксис).\\n\\n- \`404 Not Found\` — запитуваний ресурс не знайдено.\\n\\n- \`403 Forbidden\` — доступ заборонено (немає прав).\\n\\n- 5xx (Серверні помилки) — сервер не зміг обробити коректний запит.\\n\\n- \`500 Internal Server Error\` — загальна помилка сервера (наприклад, збій у коді).\\n\\n- \`502 Bad Gateway\` — проксі-сервер отримав недопустиму відповідь від іншого сервера.\\n\\n- \`503 Service Unavailable\` — сервер тимчасово недоступний (перевантаження, техроботи).\\n\\nПриклад:\\n\\n- Якщо користувач увів невірний email у формі (\`400\`).\\n\\n- Якщо база даних на сервері впала (\`500\`).",null],[3186,"CORS (Cross-Origin Resource Sharing) — це механізм, який дозволяє вебсторінці запитувати ресурси з іншого домену, якщо сервер явно дозволив це. Без CORS браузер блокує такі запити з безпеки.","За замовчуванням браузери забороняють JavaScript-запити до іншого домену (через політику Same-Origin Policy). CORS дозволяє обійти це обмеження, якщо сервер надсилає спеціальні заголовки, наприклад:\\n\\nПриклади:\\n\\n- Простий запит (GET/POST з дозволеними заголовками):\\n\\n- Браузер автоматично додає заголовок \`Origin\`.\\n\\n- Сервер відповідає з \`Access-Control-Allow-Origin\`.\\n\\n- Попередній запит (OPTIONS):\\n\\n- Для «непростих» запитів (наприклад, з \`DELETE\` або кастомними заголовками) браузер спершу надсилає \`OPTIONS\`, щоб перевірити дозволи.\\n\\nПомилка CORS у консолі:","Access-Control-Allow-Origin: https://example.com\\n\\nAccess to fetch at 'https://api.example.com' from origin 'https://your-site.com' has been blocked by CORS policy."],[3187,"- Куки:\\n\\n- Малий розмір (~4 КБ на домен).\\n\\n- Автоматично надсилаються на сервер з кожним HTTP-запитом.\\n\\n- Можуть бути постійними (термін спливає вручну) або сеансовими (до закриття браузера).\\n\\n- Використовують для авторизації, трекінгу.\\n\\n- Session Storage:\\n\\n- Більший розмір (~5 МБ на домен).\\n\\n- Дані доступні лише в поточній вкладці й видаляються після її закриття.\\n\\n- Не надсилаються на сервер автоматично.\\n\\n- Використовують для тимчасових даних (наприклад, збереження форми).","- Час життя\\n\\n- Куки:\\n\\n- Якщо вказано параметр \`expires\` або \`max-age\`, куки зберігаються навіть після закриття браузера.\\n\\n- Без них — видаляються після завершення сеансу (але поведінка залежить від браузера).\\n\\n- Session Storage:\\n\\n- Дані живуть лише поки відкрита вкладка. Під час її закриття — очищаються.\\n\\n- Обсяг даних\\n\\n- Куки:\\n\\n- Обмеження ~4 КБ на весь домен (усі куки сумарно).\\n\\n- Переповнення призводить до втрати старих куків.\\n\\n- Session Storage:\\n\\n- До ~5 МБ на домен (залежить від браузера).\\n\\n- Можна зберігати складні дані (наприклад, JSON-об'єкти).\\n\\n- Доступність\\n\\n- Куки:\\n\\n- Автоматично прикріплюються до кожного HTTP-запиту в заголовку \`Cookie\`.\\n\\n- Сервер може читати/змінювати їх через \`Set-Cookie\`.\\n\\n- Session Storage:\\n\\n- Доступний лише через JavaScript на клієнті.\\n\\n- Не надсилається на сервер без явної вказівки (наприклад, через \`fetch\`).\\n\\n- Використання\\n\\n- Коли вибирати куки:\\n\\n- Для аутентифікації (JWT, сеансові ID).\\n\\n- Для трекінгу (аналітика, персоналізація).\\n\\n- Коли вибирати \`sessionStorage\`:\\n\\n- Тимчасові дані в межах однієї вкладки (наприклад, збереження форми перед надсиланням).\\n\\n- Кешування важких даних, щоб уникнути повторних обчислень.\\n\\n- Безпека\\n\\n- Куки:\\n\\n- Уразливі до CSRF-атак (якщо немає \`SameSite\` і \`HttpOnly\`).\\n\\n- Можна захистити:\\n\\n- Session Storage:\\n\\n- Не уразливий до CSRF (оскільки не надсилається автоматично).\\n\\n- Але уразливий до XSS (якщо зловмисник виконає чужий JS-код).","// Кука з терміном придатності (видалиться через 7 днів)\\ndocument.cookie = \\"token=abc123; max-age=604800; path=/\\";\\n\\n// HTTP-заголовок від сервера\\nSet-Cookie: sessionId=xyz; Secure; HttpOnly\\n\\n// Приклад читання куків\\nconsole.log(document.cookie); // \\"token=abc123; theme=dark\\"\\n\\n// Збереження об'єкта\\nsessionStorage.setItem('formData', JSON.stringify({ name: 'Alice', age: 25 }));\\n// Читання\\nconst data = JSON.parse(sessionStorage.getItem('formData'));\\n\\ndocument.cookie = \\"auth=secret; Secure; HttpOnly; SameSite=Strict\\";"],[3188,"CSRF-атаки можливі, коли сайт автоматично надсилає облікові дані (наприклад, куки сеансу) без підтвердження користувача. Основні ризики — звичайні куки, Basic Auth і автоматична прив'язка токенів до запитів.","CSRF (Cross-Site Request Forgery) — це атака, за якої зловмисник змушує браузер жертви виконувати небажані запити до довіреного сайту. Уразливі механізми, де:\\n\\n- Куки сеансу — браузер автоматично прикріплює їх до кожного запиту.\\n\\n- Basic Auth — якщо логін/пароль кешуються браузером.\\n\\n- Автоматичні токени — наприклад, у hidden-полях форм без додаткових перевірок.\\n\\nЯк захиститися:\\n\\n- Використовувати CSRF-токени (генеруються сервером і перевіряються для кожного POST/PUT/DELETE).\\n\\n- Задавати кукам атрибут \`SameSite=Strict\` або \`Lax\`.\\n\\n- Для API застосовувати OAuth 2.0 з Proof Key for Code Exchange (PKCE).\\n\\nПриклад CSRF-токена у формі:","<form action=\\"/transfer\\" method=\\"POST\\">\\n  <input type=\\"hidden\\" name=\\"csrf_token\\" value=\\"випадковий_рядок_від_сервера\\">\\n  <input type=\\"text\\" name=\\"amount\\">\\n</form>"],[3189,"gRPC дає високу продуктивність і двійкову серіалізацію Protobuf, підтримує стримінг, строгу типізацію й автоматичну генерацію коду, але потребує HTTP/2, складніший у зневадженні й не так широко підтримується браузерами. REST з JSON простіший в освоєнні, сумісніший з HTTP/1.1 і широко підтримується в інструментах, але поступається за швидкістю та повнотою контрактів.","Переваги gRPC:\\n\\n- Продуктивність: бінарний протокол Protobuf + HTTP/2.\\n\\n- Строга типізація: \`.proto\` описує сервіс і повідомлення.\\n\\n- Стримінг: легко реалізувати клієнт/сервер-стрими.\\n\\n- Кодогенерація: клієнти/сервери для багатьох мов.\\n\\nНедоліки gRPC:\\n\\n- Потребує HTTP/2, не завжди підтримується в браузерах (потрібен gRPC-Web).\\n\\n- Менша людиночитність повідомлень (Protobuf vs JSON).\\n\\n- Складніше зневаджувати (потрібні спеціальні інструменти).\\n\\nREST/JSON:\\n\\n- Широка сумісність, простота зневадження через curl/браузер.\\n\\n- Підходить для публічних API, де важлива простота.\\n\\n- Більший трафік (текстовий JSON), відсутній стримінг за замовчуванням, немає автоматичного контракту.\\n\\nВисновок:\\n\\n- Вибирайте gRPC для високопродуктивних мікросервісів і внутрішніх сервісів.\\n\\n- REST — для публічних HTTP API і простих інтеграцій.",null],[3190,"Коди 4xx означають помилки клієнта: запит був невірним або неавторизованим. Коди 5xx указують на помилки сервера: на стороні API або вебсервера сталася внутрішня проблема.","Діапазон 4xx (Client Error)\\n\\n- 400 Bad Request: некоректний синтаксис запиту.\\n\\n- 401 Unauthorized: відсутній або невірний токен авторизації.\\n\\n- 403 Forbidden: доступ заборонено, навіть якщо авторизовані.\\n\\n- 404 Not Found: ресурс не знайдено.\\n\\n- Коли застосовувати: повернути за невірних даних від клієнта або спроби доступу без прав.\\n\\nДіапазон 5xx (Server Error)\\n\\n- 500 Internal Server Error: загальна внутрішня помилка сервера.\\n\\n- 502 Bad Gateway: проміжний сервер отримав невірну відповідь.\\n\\n- 503 Service Unavailable: сервіс тимчасово недоступний (перевантаження, техроботи).\\n\\n- 504 Gateway Timeout: проміжний сервер не дочекався відповіді.\\n\\n- Коли застосовувати: використовувати під час збоїв, непередбачених винятків або за планового техобслуговування.\\n\\nІдемо за сценарієм:\\n\\n- Клієнт надсилає невірний JSON → 400.\\n\\n- Користувач неавторизований → 401.\\n\\n- Сервіс упав через помилку в коді → 500.",null],[3191,"503 означає, що сервер тимчасово не може обробити запит через перевантаження або технічне обслуговування. Клієнтам звичайно пропонують повторити спробу пізніше.","Суть стану 503\\n\\n- HTTP-код 503 означає «Service Unavailable».\\n\\n- Сервер функціонує, але в цей момент не може обробити запит.\\n\\nТипові причини\\n\\n- Перевантаження (вибух трафіку).\\n\\n- Планове або екстрене техобслуговування.\\n\\n- Обмеження ресурсів (CPU, пам'ять, з'єднання).\\n\\nРекомендації для клієнта\\n\\n- Повторити запит через деякий час.\\n\\n- Використовувати експоненційний бекоф (зростаючий інтервал).\\n\\nПриклад заголовка Retry-After\\n\\nТут клієнтові радять почекати 120 секунд.\\nВисновок:\\n\\n- Застосовувати 503, коли відмова не постійна і є плани відновлення.\\n\\n- Для довгого простою варто використовувати сторінку з повідомленням про техроботи.","HTTP/1.1 503 Service Unavailable\\nRetry-After: 120"],[3192,"HTTP передає дані у відкритому вигляді, а HTTPS — через захищений канал TLS/SSL. HTTPS шифрує трафік, що захищає від перехоплення й підміни.","HTTP (HyperText Transfer Protocol)\\n\\n- Протокол передавання гіпертексту поверх TCP.\\n\\n- Дані йдуть у відкритому вигляді.\\n\\n- Уразливий до «прослуховування» й атак «людина посередині».\\n\\nHTTPS (HTTP Secure)\\n\\n- HTTP поверх TLS/SSL.\\n\\n- Шифрує канал: аутентифікація сервера, опціонально клієнта.\\n\\n- Використовує сертифікати X.509 для перевірки справжності.\\n\\nЕтапи встановлення HTTPS-сеансу\\n\\n- Клієнт запитує сертифікат сервера.\\n\\n- Перевіряє довірений центр сертифікації.\\n\\n- Домовляються про симетричний ключ.\\n\\n- Далі весь трафік шифрується.\\n\\nКоли застосовувати:\\n\\n- Завжди для передавання особистих даних, авторизації, оплати.\\n\\n- Для публічних сайтів — за замовчуванням (Let's Encrypt).",null],[3193,"GET — читання (Read); POST — створення (Create); PUT/PATCH — оновлення (Update); DELETE — видалення (Delete). PUT заміняє весь ресурс, PATCH вносить часткові зміни.","Create (C)\\n\\n- POST: створює новий ресурс, URI генерує сервер.\\n\\n- Приклад: \`POST /users\` з JSON-тілом → новий користувач.\\n\\nRead (R)\\n\\n- GET: запитує представлення або дані без зміни.\\n\\n- Приклад: \`GET /users/123\`.\\n\\nUpdate (U)\\n\\n- PUT: повна заміна ресурсу; якщо немає — може створити.\\n\\n- PATCH: часткова зміна полів ресурсу.\\n\\n- Приклад PATCH: \`PATCH /users/123\` з \`{ \\"email\\": \\"new@mail\\" }\`.\\n\\nDelete (D)\\n\\n- DELETE: видаляє ресурс за вказаною URI.\\n\\nІдемпотентність\\n\\n- GET, PUT, DELETE — ідемпотентні: багаторазові виклики дають той самий результат.\\n\\n- POST, PATCH — не завжди ідемпотентні.",null],[3194,"GET передає параметри в URL, яка може потрапити в логи, історію браузера й бути закешована. Це робить передавання чутливих даних уразливим. Краще використовувати POST із тілом запиту.","Параметри в URL\\n\\n- Усі дані видні в рядку запиту (\`?user=alice&token=…\`).\\n\\n- URL зберігаються в історії та логах вебсервера.\\n\\nКешування\\n\\n- Проксі та браузери можуть кешувати GET-відповідь.\\n\\n- Потенційно секретні параметри зберігаються в кеші.\\n\\nОбмеження довжини\\n\\n- Браузери/сервери обмежують довжину URL (звичайно ~2000 символів).\\n\\nРекомендації\\n\\n- Для передавання логінів, паролів, токенів — використовувати POST або інші методи з тілом.\\n\\n- Завжди застосовувати HTTPS для шифрування.",null],[3195,"PUT заміняє весь ресурс новим представленням, а PATCH змінює лише вказані поля. PUT звичайно ідемпотентний, PATCH — може бути частково ідемпотентним залежно від реалізації.","PUT (повна заміна)\\n\\n- Клієнт надсилає повну модель ресурсу.\\n\\n- Відсутні поля можуть бути скинуті до значень за замовчуванням або видалені.\\n\\n- Ідемпотентний: багаторазові виклики — той самий результат.\\n\\nPATCH (часткове оновлення)\\n\\n- Клієнт надсилає лише змінені поля.\\n\\n- Залишає решту даних без змін.\\n\\n- Може використовувати різні формати (JSON-Patch, Merge Patch).\\n\\nПриклад JSON-Merge Patch\\n\\nзаміняє лише email, не торкаючись інших полів.\\nКоли застосовувати:\\n\\n- PUT — коли потрібен повний апдейт або під час створення ресурсу за відомою URI.\\n\\n- PATCH — для заощадження трафіку та зручності часткових змін.","PATCH /users/123\\nContent-Type: application/merge-patch+json\\n\\n{\\n    \\"email\\": \\"new@example.com\\"\\n}"],[3196,"Так, згідно зі специфікацією HTTP PUT може створювати новий ресурс на вказаній URI, якщо він не існує. Проте це залежить від реалізації API й не завжди є рекомендацією.","Специфікація HTTP\\n\\n- PUT — може створити ресурс на цільовій URI, якщо сервер підтримує таку логіку.\\n\\nІдемпотентність\\n\\n- Перший PUT створює ресурс, наступні з тими самими даними не змінять нічого.\\n\\nРекомендована практика\\n\\n- Створювати через POST, якщо URI генерує сервер.\\n\\n- Використовувати PUT-створення, коли клієнт сам визначає ідентифікатор ресурсу.\\n\\nПриклад створення через PUT:\\n\\nстворює користувача з ID «alice».\\nКоли застосовувати:\\n\\n- Коли важливо задати передбачувану URI.\\n\\n- Для синхронізації даних між розподіленими системами.","PUT /users/alice\\nContent-Type: application/json\\n\\n{\\n    \\"name\\": \\"Alice\\",\\n    \\"email\\": \\"alice@example.com\\"\\n}"],[3197,"У CI/CD-пайплайн додають крок, який запускає автотести (юніт, інтеграційні, e2e) за кожного коміту або pull request. Звичайно для цього використовують CI-системи (GitHub Actions, GitLab CI, Jenkins та ін.) із конфігураційними файлами, де прописано команди запуску тестів, установлення залежностей і звітність за результатами.","Підготовка оточення:\\n\\n- Указують базовий образ або машину (Docker-контейнер, VM).\\n\\n- Установлюють залежності (бібліотеки, бази даних, сервіси).\\n\\nДодавання кроку тестування:\\nУ конфігу CI (наприклад, \`.gitlab-ci.yml\` або \`.github/workflows/ci.yml\`) описують job, який виконує:\\n\\n- \`checkout\` коду.\\n\\n- Установлення залежностей (\`npm install\`, \`pip install -r requirements.txt\`).\\n\\n- Запуск тестів (\`pytest\`, \`npm test\` тощо).\\n\\nЗвіти й артефакти:\\n\\n- Генерація звітів (JUnit, HTML, код-cov).\\n\\n- Публікація артефактів для аналізу покриття.\\n\\nПаралелізація та кешування:\\n\\n- Розбиття тестів на кілька job для пришвидшення.\\n\\n- Кешування залежностей між запусками.\\n\\nFail-fast і повідомлення:\\n\\n- Конфігурація припинення пайплайна за невдалих тестів (fail-fast).\\n\\n- Налаштування оповіщень (e-mail, Slack).",null],[3198,"Cookie зберігаються в браузері користувача й надсилаються на сервер з кожним запитом. Сеанси звичайно зберігаються на сервері (наприклад, у базі даних або Redis), а в браузері зберігається лише ідентифікатор сеансу (часто в cookie).","Cookie — це невеликі текстові файли, які зберігаються в браузері. Їх використовують для аутентифікації, відстеження користувачів і зберігання налаштувань. Наприклад, коли ви входите на сайт, сервер може надіслати cookie з токеном авторизації.\\nСеанси — це дані, які зберігаються на сервері. Замість того щоб передавати всі дані туди-назад, сервер створює унікальний ідентифікатор сеансу (наприклад, \`session_id\`) і зберігає його в cookie браузера. За кожного запиту сервер перевіряє цей ідентифікатор і завантажує дані сеансу зі свого сховища (бази даних, Redis тощо).\\nПриклад cookie:\\n\\nПриклад сеансу в Redis:","Set-Cookie: session_id=abc123; Path=/; HttpOnly\\n\\n{\\n  \\"session_id\\": \\"abc123\\",\\n  \\"user_id\\": 42,\\n  \\"last_activity\\": \\"2023-10-01T12:00:00Z\\"\\n}"],[3199,"Запит \`OPTIONS\` надсилається браузером автоматично перед деякими HTTP-запитами (наприклад, \`POST\` або \`DELETE\` з особливими заголовками). Це частина механізму CORS — він перевіряє, чи дозволено запит сервером.","Коли фронтенд і бекенд на різних доменах (наприклад, \`frontend.com\` і \`api.backend.com\`), браузер блокує «небезпечні» запити з міркувань безпеки. Щоб переконатися, що сервер дозволяє такі запити, браузер спершу надсилає \`OPTIONS\` (preflight-запит).\\nПриклад:\\n\\n- Фронтенд надсилає \`POST /data\` із заголовком \`Content-Type: application/json\`.\\n\\n- Браузер спершу надсилає:\\n\\n- Сервер відповідає:\\n\\n- Якщо відповідь сервера дозволяє запит, браузер надсилає основний \`POST\`.","OPTIONS /data HTTP/1.1\\nHost: api.backend.com\\nOrigin: https://frontend.com\\nAccess-Control-Request-Method: POST\\n\\nHTTP/1.1 204 No Content\\nAccess-Control-Allow-Origin: https://frontend.com\\nAccess-Control-Allow-Methods: POST, GET"],[3200,"Для отримання даних у реальному часі використовують:\\n\\n- WebSocket — двостороннє з'єднання між клієнтом і сервером.\\n\\n- Server-Sent Events (SSE) — потік односторонніх повідомлень від сервера.\\n\\n- Long Polling — запити з довгим очікуванням відповіді.","1. WebSocket\\nПротокол ws:// або wss:// (безпечний), який підтримує двосторонній зв'язок.\\nПриклад:\\n\\nПлюси:\\n\\n- Миттєве передавання даних.\\n\\n- Підтримка бінарних даних.\\n\\nМінуси:\\n\\n- Складніший у налаштуванні сервера.\\n\\n2. Server-Sent Events (SSE)\\nОдносторонній потік даних від сервера (наприклад, для повідомлень).\\nКлієнтський код:\\n\\nСервер (Node.js + Express):\\n\\nПлюси:\\n\\n- Простота реалізації.\\n\\n- Автоматичне перепідключення.\\n\\nМінуси:\\n\\n- Лише сервер → клієнт.\\n\\n3. Long Polling\\nКлієнт надсилає запит, а сервер відповідає лише коли є дані.\\nПриклад:\\n\\nПлюси:\\n\\n- Працює навіть без WebSocket.\\n\\nМінуси:\\n\\n- Високе навантаження на сервер.","const socket = new WebSocket('wss://example.com/ws');\\n\\nsocket.onopen = () => console.log('З\\\\'єднання встановлено');  \\nsocket.onmessage = (event) => console.log('Отримано:', event.data);  \\nsocket.onclose = () => console.log('З\\\\'єднання закрито');  \\n\\n// Надсилання даних  \\nsocket.send('Привіт, сервере!');\\n\\nconst eventSource = new EventSource('/updates');  \\n\\neventSource.onmessage = (event) => {  \\n    console.log('Нове повідомлення:', event.data);  \\n};\\n\\napp.get('/updates', (req, res) => {  \\n    res.setHeader('Content-Type', 'text/event-stream');  \\n    setInterval(() => {  \\n        res.write(\`data: \${new Date().toISOString()}\\\\n\\\\n\`);  \\n   }, 1000);  \\n});\\n\\nfunction fetchUpdates() {  \\n    fetch('/poll')  \\n        .then(response => response.json())  \\n        .then(data => {  \\n            console.log('Дані:', data);  \\n            fetchUpdates(); // Новий запит  \\n        });  \\n}"]]`);export{e as default};